insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations, aliases) values
('378', '자만추', 'Ja-Man-Chu', 'love', null, '자연스러운 만남을 추구하는 연애관', '{"en": "Preferring to meet someone naturally, not through setups", "ja": "自然な出会いを求める恋愛観", "es": "Preferir conocer a alguien de forma natural", "vi": "Thích gặp gỡ tự nhiên hơn là mai mối", "de": "Lieber natürlich jemanden kennenlernen als über Vermittlung"}'::jsonb, '[자만추]', '[{"type": "명사", "definition": "''자연스러운 만남 추구''의 준말. 소개팅이나 앱처럼 일부러 자리를 만들지 않고, 학교·회사·취미 모임처럼 일상 속에서 알게 된 사람과 이어지기를 바라는 연애관이다. ''인만추''(인위적인 만남 추구)와 짝을 이룬다.", "definition_i18n": {"en": "Short for 자연스러운 만남 추구, ''seeking a natural meeting'' — preferring to end up with someone you already met through school, work or a hobby, rather than through a set-up or an app. It pairs with 인만추, its arranged-meeting opposite.", "ja": "「自然な出会い追求」の略。合コンやアプリのように場を作るのではなく、学校・職場・趣味の集まりなど日常の中で知り合った相手とつながりたいという恋愛観。対になる語は「인만추」(人為的な出会い追求)。", "es": "Abreviatura de 자연스러운 만남 추구, ''buscar un encuentro natural'': preferir acabar con alguien que ya conociste en clase, en el trabajo o en una afición, antes que por una cita concertada o una app. Hace pareja con 인만추.", "vi": "Viết tắt của 자연스러운 만남 추구, ''tìm cuộc gặp tự nhiên'' — thích đến với người đã quen ở trường, chỗ làm hay nhóm sở thích, hơn là qua mai mối hoặc app. Đi cặp với 인만추.", "de": "Kurz für 자연스러운 만남 추구, ''ein natürliches Kennenlernen suchen'' — lieber mit jemandem zusammenkommen, den man ohnehin aus Uni, Job oder Hobby kennt, als über Vermittlung oder App. Gegenstück ist 인만추."}, "examples": [{"kor": "나는 자만추라서 소개팅은 잘 안 나가.", "eng": "I''m a 자만추 type, so I don''t really go on set-up dates.", "ja": "私は자만추だから合コンにはあまり行かない。", "es": "Soy de 자만추, así que no suelo ir a citas concertadas.", "vi": "Tao kiểu 자만추 nên ít đi xem mắt lắm.", "de": "Ich bin eher 자만추, deshalb gehe ich selten zu vermittelten Dates."}]}, {"type": "명사", "adult_only": true, "definition": "(비속한 용법) ''자보고 만남 추구''의 준말로 비틀어 쓰는 경우. 사귀기 전에 먼저 잠자리를 갖고, 맞으면 만남을 이어간다는 뜻이다. 2020년대 들어 젊은 층에서 원래 뜻을 농담처럼 비틀며 생긴 용법이라 맥락 없이 쓰면 오해를 산다.", "definition_i18n": {"en": "(crude use) The same letters read as 자보고 만남 추구, ''sleep together first, then decide'' — hooking up before dating and continuing only if it works. It came up in the 2020s as a joking twist on the original sense, so it invites misunderstanding out of context.", "ja": "(下品な用法)同じ略を「寝てから付き合う追求」と読み替えたもの。先に関係を持ち、合えば交際を続けるという意味。2020年代に本来の意味をふざけてひねって生まれた用法で、文脈なしに使うと誤解を招く。", "es": "(uso grosero) Las mismas siglas leídas como 자보고 만남 추구, ''acostarse primero y luego decidir'': tener relaciones antes de salir y seguir solo si encaja. Surgió en los 2020 como una vuelta de tuerca jocosa al sentido original, así que fuera de contexto se malinterpreta.", "vi": "(cách dùng thô) Cùng chữ viết tắt nhưng đọc thành 자보고 만남 추구, ''ngủ trước rồi tính'' — quan hệ trước khi yêu, hợp thì tiếp tục. Xuất hiện thập niên 2020 như một cách bẻ đùa nghĩa gốc, nên dùng không đúng ngữ cảnh dễ bị hiểu lầm.", "de": "(derbe Verwendung) Dieselbe Abkürzung gelesen als 자보고 만남 추구, ''erst miteinander schlafen, dann entscheiden'' — vor der Beziehung Sex, und nur weitermachen, wenn es passt. Kam in den 2020ern als scherzhafte Verdrehung des ursprünglichen Sinns auf und wird ohne Kontext leicht missverstanden."}, "examples": [{"kor": "걔가 자만추라길래 자연스러운 만남인 줄 알았는데 아니었어.", "eng": "They said they were 자만추 — I assumed they meant meeting naturally. They didn''t.", "ja": "あの子が자만추だって言うから自然な出会いのことかと思ったら違った。", "es": "Dijo que era de 자만추 y pensé que hablaba de conocerse naturalmente. No era eso.", "vi": "Nó bảo nó 자만추, tao tưởng là gặp gỡ tự nhiên, hóa ra không phải.", "de": "Er sagte, er sei 자만추 — ich dachte, es ginge ums natürliche Kennenlernen. War es nicht."}]}]'::jsonb, '''자연스러운 만남 추구''를 네 글자로 줄인 말이다. 2018년 무렵 예능과 온라인 커뮤니티에서 ''인만추''와 짝으로 퍼지며 실시간 검색어에 오를 만큼 대중화됐다. 이후 2020년대 들어 같은 줄임을 ''자보고 만남 추구''로 비트는 용법이 20대 초반에서 생겨났는데, 어느 쪽이 먼저 비틀었는지는 확인되지 않았다.', '{"en": "A four-syllable clipping of 자연스러운 만남 추구. It spread around 2018 alongside 인만추 through variety shows and online communities, popular enough to reach the real-time search rankings. In the 2020s younger speakers began reading the same clipping as 자보고 만남 추구; who twisted it first is unverified.", "ja": "「자연스러운 만남 추구」を四文字に略した語。2018年ごろ「인만추」と対でバラエティやネットコミュニティを通じて広まり、リアルタイム検索に載るほど大衆化した。2020年代に入り同じ略を「자보고 만남 추구」と読み替える用法が20代前半で生まれたが、誰が先に始めたかは未確認。", "es": "Recorte de cuatro sílabas de 자연스러운 만남 추구. Se difundió hacia 2018 junto a 인만추 por programas de variedades y foros, hasta llegar a las búsquedas del momento. En los 2020 los más jóvenes empezaron a leer el mismo recorte como 자보고 만남 추구; quién lo torció primero no está verificado.", "vi": "Dạng rút gọn bốn âm tiết của 자연스러운 만남 추구. Lan khoảng năm 2018 cùng với 인만추 qua show giải trí và cộng đồng mạng, phổ biến tới mức lọt top tìm kiếm. Sang thập niên 2020, giới trẻ bắt đầu đọc chính chữ tắt đó thành 자보고 만남 추구; ai bẻ nghĩa đầu tiên thì chưa xác minh.", "de": "Eine viersilbige Kürzung von 자연스러운 만남 추구. Sie verbreitete sich um 2018 zusammen mit 인만추 über Varieté-Shows und Online-Foren, populär genug für die Echtzeit-Suchcharts. In den 2020ern lasen jüngere Sprecher dieselbe Kürzung als 자보고 만남 추구; wer sie zuerst verdrehte, ist ungeprüft."}'::jsonb, '연애 스타일을 말할 때 ''나는 자만추야''처럼 자기소개하듯 쓴다. 다만 젊은 층에는 성적인 의미로 비트는 용법도 있어, 처음 만난 사이에서 쓰면 의도와 다르게 읽힐 수 있다.', '{"en": "Used to describe your dating style, almost as a self-introduction: ''나는 자만추야''. Be aware that younger speakers also use it in a sexual sense, so with someone you''ve just met it can land differently than you intend.", "ja": "恋愛スタイルを言うとき「私は자만추だ」と自己紹介のように使う。ただし若い層には性的な意味にひねる用法もあるので、初対面で使うと意図と違う受け取られ方をすることがある。", "es": "Se usa para describir tu estilo amoroso, casi como presentación: ''나는 자만추야''. Ten en cuenta que entre jóvenes también tiene un sentido sexual, así que con alguien que acabas de conocer puede entenderse distinto de lo que quieres.", "vi": "Dùng để nói về gu yêu đương của mình, gần như tự giới thiệu: ''나는 자만추야''. Lưu ý giới trẻ còn dùng theo nghĩa tình dục, nên với người mới quen có thể bị hiểu khác ý.", "de": "Man beschreibt damit seinen Beziehungsstil, fast wie eine Vorstellung: ''나는 자만추야''. Beachte, dass jüngere Sprecher es auch sexuell meinen — bei jemandem, den du gerade erst kennengelernt hast, kann es anders ankommen als gemeint."}'::jsonb, array['인만추','썸','헌팅'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Meeting someone naturally"}, {"lang": "🇯🇵 JA", "text": "自然な出会い派"}, {"lang": "🇨🇳 ZH", "text": "追求自然相识"}, {"lang": "🇻🇳 VI", "text": "Thích gặp tự nhiên"}, {"lang": "🇪🇸 ES", "text": "Encuentro natural"}, {"lang": "🇩🇪 DE", "text": "Natürliches Kennenlernen"}]'::jsonb, array[]::text[]),
('379', '인만추', 'In-Man-Chu', 'love', null, '소개팅처럼 자리를 만들어 만나는 걸 선호하는 연애관', '{"en": "Preferring set-ups and apps to chance meetings", "ja": "合コンやアプリなど、場を作って出会うのを好む恋愛観", "es": "Preferir citas concertadas a encuentros casuales", "vi": "Thích mai mối, app hơn là gặp tình cờ", "de": "Lieber über Vermittlung oder App jemanden treffen"}'::jsonb, '[인만추]', '[{"type": "명사", "definition": "''인위적인 만남 추구''의 준말. 소개팅·미팅·데이팅 앱처럼 만남의 자리를 일부러 만들어 이성을 만나는 쪽을 선호하는 연애관이다. ''자만추''와 짝을 이루며, 연애 의지가 적극적인 쪽으로 통한다.", "definition_i18n": {"en": "Short for 인위적인 만남 추구, ''seeking an arranged meeting'' — preferring to meet people through set-ups, group dates or dating apps rather than waiting for chance. The counterpart to 자만추, and read as the more proactive stance.", "ja": "「人為的な出会い追求」の略。紹介・合コン・マッチングアプリのように出会いの場をあえて作って異性と会う方を好む恋愛観。「자만추」と対になり、恋愛に積極的な側と受け取られる。", "es": "Abreviatura de 인위적인 만남 추구, ''buscar un encuentro provocado'': preferir conocer gente por citas concertadas, quedadas en grupo o apps, en vez de esperar a la casualidad. Es el reverso de 자만추 y se lee como la postura más activa.", "vi": "Viết tắt của 인위적인 만남 추구, ''tìm cuộc gặp có sắp đặt'' — thích quen qua mai mối, hẹn nhóm hay app hơn là chờ duyên. Đối lập với 자만추 và được xem là chủ động hơn.", "de": "Kurz für 인위적인 만남 추구, ''ein arrangiertes Kennenlernen suchen'' — lieber über Vermittlung, Gruppendates oder Apps jemanden treffen, statt auf den Zufall zu warten. Gegenstück zu 자만추 und gilt als die aktivere Haltung."}, "examples": [{"kor": "자만추 기다리다 지쳐서 이제 인만추로 갈아탔어.", "eng": "I got tired of waiting for something natural, so I''ve switched to 인만추.", "ja": "자만추を待つのに疲れて、今は인만추に切り替えた。", "es": "Me cansé de esperar algo natural, así que ahora voy de 인만추.", "vi": "Chờ duyên tự nhiên mãi mệt quá, giờ tao chuyển sang 인만추.", "de": "Ich hatte es satt, auf etwas Natürliches zu warten, jetzt bin ich 인만추."}]}]'::jsonb, '''인위적인 만남 추구''를 줄인 말로, ''자만추''와 한 쌍으로 만들어져 함께 퍼졌다. 2018년 무렵 두 말이 예능과 커뮤니티에서 동시에 대중화됐고, 어느 쪽이 먼저 생겼는지는 출처가 특정하지 않는다.', '{"en": "A clipping of 인위적인 만남 추구, coined as one half of a pair with 자만추 and spread alongside it. Both hit the mainstream around 2018 through variety shows and online communities; sources don''t say which came first.", "ja": "「인위적인 만남 추구」の略で、「자만추」と一対で作られ一緒に広まった。2018年ごろ両語が同時にバラエティとコミュニティで大衆化し、どちらが先かは出典が特定していない。", "es": "Recorte de 인위적인 만남 추구, acuñado como mitad de una pareja con 자만추 y difundido junto a él. Ambos se popularizaron hacia 2018 por programas y foros; las fuentes no dicen cuál fue primero.", "vi": "Rút gọn của 인위적인 만남 추구, được tạo thành cặp với 자만추 và lan cùng nhau. Cả hai phổ biến khoảng 2018 qua show giải trí và cộng đồng mạng; nguồn không nói từ nào có trước.", "de": "Kürzung von 인위적인 만남 추구, als Hälfte eines Paares mit 자만추 geprägt und gemeinsam verbreitet. Beide wurden um 2018 über Varieté-Shows und Foren populär; die Quellen sagen nicht, welches zuerst kam."}'::jsonb, '''자만추/인만추 중에 뭐야?''처럼 둘을 놓고 고르는 질문으로 가장 많이 쓴다. 부정적인 말은 아니고, 연애에 적극적이라는 뉘앙스에 가깝다.', '{"en": "Most often appears as a choice between the two: ''are you 자만추 or 인만추?''. It isn''t an insult — it reads as being upfront about wanting to date.", "ja": "「자만추と인만추のどっち?」のように二択で聞く形で使うのが最も多い。悪い意味ではなく、恋愛に積極的というニュアンスに近い。", "es": "Suele aparecer como elección entre los dos: ''¿eres de 자만추 o de 인만추?''. No es un insulto: suena a ser claro sobre que quieres pareja.", "vi": "Hay xuất hiện dưới dạng chọn một trong hai: ''mày 자만추 hay 인만추?''. Không phải chê, mà nghe như thẳng thắn muốn yêu.", "de": "Meist als Wahl zwischen beiden: ''Bist du 자만추 oder 인만추?''. Kein Vorwurf — es klingt danach, offen zu sagen, dass man jemanden sucht."}'::jsonb, array['자만추','헌팅','애프터'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Meeting through set-ups"}, {"lang": "🇯🇵 JA", "text": "人為的な出会い派"}, {"lang": "🇨🇳 ZH", "text": "追求安排相识"}, {"lang": "🇻🇳 VI", "text": "Thích gặp qua mai mối"}, {"lang": "🇪🇸 ES", "text": "Encuentro concertado"}, {"lang": "🇩🇪 DE", "text": "Arrangiertes Kennenlernen"}]'::jsonb, array[]::text[]),
('380', '헌팅', 'Heon-Ting', 'love', null, '길이나 클럽에서 모르는 이성에게 말을 거는 것', '{"en": "Approaching a stranger on the street or in a club", "ja": "街やクラブで見知らぬ異性に声をかけること", "es": "Abordar a un desconocido en la calle o en un local", "vi": "Bắt chuyện với người lạ trên phố hay trong club", "de": "Fremde auf der Straße oder im Club ansprechen"}'::jsonb, '[헌팅]', '[{"type": "명사", "definition": "모르는 이성에게 교제를 목적으로 다가가 말을 거는 것. 영어 hunting에서 왔지만 영어에는 이런 뜻이 없는 콩글리시다. 보통 말 걸기 → 번호 받기 → 따로 만나기 순서로 진행되며, 클럽·거리·술집이 주 무대다.", "definition_i18n": {"en": "Walking up to a stranger you''re attracted to and striking up a conversation. From English ''hunting'', but the English word carries no such meaning — this is Konglish. It usually runs approach, get their number, meet up later, and happens on the street, in bars or in clubs.", "ja": "見知らぬ異性に交際を目的として近づき声をかけること。英語のhuntingから来ているが英語にこの意味はなく、韓国式英語。普通は声かけ→番号交換→後日会う、の順に進み、街・バー・クラブが主な舞台。", "es": "Acercarse a un desconocido que te atrae y entablar conversación. Del inglés ''hunting'', aunque en inglés no significa eso: es konglish. Suele ir de abordar a pedir el número y quedar después, y ocurre en la calle, en bares o discotecas.", "vi": "Tiến đến bắt chuyện với người lạ mình thấy hợp, nhằm mục đích hẹn hò. Từ ''hunting'' tiếng Anh nhưng tiếng Anh không có nghĩa này — đây là Konglish. Thường theo trình tự bắt chuyện, xin số, rồi hẹn gặp; diễn ra trên phố, quán bar hay club.", "de": "Eine fremde Person, die einem gefällt, ansprechen. Von englisch ''hunting'', obwohl das englische Wort das nicht bedeutet — Konglisch. Üblicher Ablauf: ansprechen, Nummer bekommen, später treffen; auf der Straße, in Bars oder Clubs."}, "examples": [{"kor": "어제 홍대에서 헌팅 당했는데 좀 부담스러웠어.", "eng": "Someone came up to me in Hongdae yesterday — it was a bit much.", "ja": "昨日ホンデで声をかけられたけど、ちょっと重かった。", "es": "Ayer me abordaron en Hongdae y fue un poco incómodo.", "vi": "Hôm qua bị bắt chuyện ở Hongdae, hơi ngợp.", "de": "Gestern hat mich jemand in Hongdae angesprochen — war mir etwas zu viel."}]}]'::jsonb, '영어 hunting(사냥)을 사람에게 옮겨 쓴 콩글리시다. 언제부터 이 뜻으로 굳었는지는 확인되지 않으며, 나무위키 등에서 클럽·거리 문화와 함께 설명한다. 영어권에서 같은 행동은 hitting on someone으로, hunting은 쓰지 않는다.', '{"en": "Konglish that transfers English ''hunting'' onto people. When it settled into this sense is unverified; Korean references describe it alongside club and street culture. English speakers say ''hitting on someone'' — never ''hunting''.", "ja": "英語hunting(狩り)を人に転用した韓国式英語。この意味でいつ定着したかは未確認で、韓国の資料はクラブ・街の文化と併せて説明する。英語圏では同じ行為をhitting on someoneと言い、huntingは使わない。", "es": "Konglish que traslada el inglés ''hunting'' a las personas. Cuándo se fijó con este sentido no está verificado; las fuentes coreanas lo explican junto a la cultura de discotecas y calle. En inglés se dice ''hitting on someone'', nunca ''hunting''.", "vi": "Konglish chuyển từ ''hunting'' tiếng Anh sang chỉ người. Không rõ định hình nghĩa này từ khi nào; nguồn Hàn giải thích cùng văn hóa club và đường phố. Người nói tiếng Anh dùng ''hitting on someone'', không dùng ''hunting''.", "de": "Konglisch, das englisch ''hunting'' auf Menschen überträgt. Wann sich diese Bedeutung festsetzte, ist ungeprüft; koreanische Quellen erklären es zusammen mit Club- und Straßenkultur. Im Englischen heißt das ''hitting on someone'', nie ''hunting''."}'::jsonb, '''헌팅하다''(말을 걸다)와 ''헌팅당하다''(말을 걸리다) 양쪽으로 쓴다. 요즘은 부담스럽다는 반응이 많아 긍정적으로만 들리지는 않는다.', '{"en": "Used both ways: 헌팅하다 (to approach) and 헌팅당하다 (to be approached). These days many people find it intrusive, so it doesn''t read as purely positive.", "ja": "「헌팅하다」(声をかける)と「헌팅당하다」(声をかけられる)の両方で使う。最近は重いという反応も多く、肯定的にだけ響くわけではない。", "es": "Se usa en ambas direcciones: 헌팅하다 (abordar) y 헌팅당하다 (ser abordado). Hoy a mucha gente le parece invasivo, así que no suena solo positivo.", "vi": "Dùng cả hai chiều: 헌팅하다 (bắt chuyện) và 헌팅당하다 (bị bắt chuyện). Giờ nhiều người thấy phiền nên không hẳn mang nghĩa tích cực.", "de": "In beide Richtungen: 헌팅하다 (ansprechen) und 헌팅당하다 (angesprochen werden). Heute empfinden es viele als aufdringlich, es klingt also nicht nur positiv."}'::jsonb, array['작업 걸다','플러팅','인만추'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Hitting on a stranger"}, {"lang": "🇯🇵 JA", "text": "ナンパ"}, {"lang": "🇨🇳 ZH", "text": "街头搭讪"}, {"lang": "🇻🇳 VI", "text": "Bắt chuyện làm quen"}, {"lang": "🇪🇸 ES", "text": "Ligar en la calle"}, {"lang": "🇩🇪 DE", "text": "Jemanden anbaggern"}]'::jsonb, array[]::text[]),
('381', '작업 걸다', 'Jak-Eop Geol-Da', 'love', null, '마음에 든 상대에게 은근히 들이대는 것', '{"en": "Making a move on someone you like", "ja": "気になる相手にそれとなく仕掛けること", "es": "Lanzarse a alguien que te gusta", "vi": "Ra chiêu tán tỉnh người mình thích", "de": "Bei jemandem, den man mag, einen Vorstoß machen"}'::jsonb, '[자거 걸다]', '[{"type": "동사구", "definition": "마음에 드는 상대의 마음을 얻으려고 의도적으로 접근하는 것. ''작업''은 원래 일을 한다는 뜻이지만, 여기서는 연애를 하나의 공정처럼 빗대 ''작업을 건다''고 한다. 계획적이고 능숙하다는 뉘앙스가 있어, 진심보다 기술로 읽힐 때도 있다.", "definition_i18n": {"en": "Deliberately approaching someone to win them over. 작업 normally means ''work'' or ''a job''; here courtship is framed as a job you set in motion. It carries a calculated, practised nuance, so it can read as technique rather than sincerity.", "ja": "気になる相手の心を得ようと意図的に近づくこと。「작업」は本来「作業」の意味だが、ここでは恋愛を一つの工程に見立てて「作業をかける」と言う。計画的で手慣れたニュアンスがあり、本心よりテクニックと受け取られることもある。", "es": "Acercarse a alguien a propósito para conquistarlo. 작업 significa normalmente ''trabajo''; aquí el cortejo se plantea como una faena que se pone en marcha. Tiene un matiz calculado y con oficio, así que puede leerse como técnica más que como sinceridad.", "vi": "Cố ý tiếp cận ai đó để chiếm được cảm tình. 작업 vốn nghĩa là ''công việc''; ở đây chuyện tán tỉnh được ví như một công đoạn được khởi động. Mang sắc thái có tính toán, thành thạo, nên đôi khi nghe như kỹ thuật hơn là thật lòng.", "de": "Jemanden gezielt ansprechen, um ihn für sich zu gewinnen. 작업 heißt normalerweise ''Arbeit''; hier wird das Werben wie ein Arbeitsgang aufgefasst, den man in Gang setzt. Der Ton ist berechnend und routiniert, kann also eher nach Technik als nach Aufrichtigkeit klingen."}, "examples": [{"kor": "쟤 아까부터 너한테 작업 거는 거 몰랐어?", "eng": "You didn''t notice they''ve been making a move on you this whole time?", "ja": "あの子さっきからあなたに仕掛けてるの気づかなかった?", "es": "¿No te diste cuenta de que lleva un rato lanzándose a ti?", "vi": "Mày không nhận ra nó tán mày từ nãy giờ à?", "de": "Hast du nicht gemerkt, dass er die ganze Zeit bei dir landen will?"}]}]'::jsonb, '''작업(作業)''에 ''걸다''를 붙인 관용 표현이다. 표준국어대사전에 ''작업''은 ''일을 함''으로만 올라 있고 이 연애 뜻은 등재돼 있지 않다. 언제부터 이 뜻으로 쓰였는지는 확인되지 않으며, 영화·드라마 대사를 통해 굳은 것으로 이야기된다.', '{"en": "An idiom built from 작업 (''work'') plus 걸다 (''to set going''). The standard Korean dictionary lists 작업 only as ''doing work'' — this romantic sense isn''t in it. When it took hold is unverified; it''s usually described as settling in through film and drama dialogue.", "ja": "「작업(作業)」に「걸다(かける)」を付けた慣用表現。標準国語大辞典に「작업」は「仕事をすること」としか載っておらず、この恋愛の意味は未収録。いつからこの意味で使われたかは未確認で、映画やドラマの台詞を通じて定着したと語られる。", "es": "Locución formada por 작업 (''trabajo'') más 걸다 (''echar a andar''). El diccionario estándar solo recoge 작업 como ''hacer un trabajo''; este sentido amoroso no figura. Cuándo se asentó no está verificado; suele decirse que cuajó por diálogos de cine y series.", "vi": "Thành ngữ ghép 작업 (''công việc'') với 걸다 (''khởi động''). Từ điển chuẩn chỉ ghi 작업 là ''làm việc'', không có nghĩa tán tỉnh này. Không rõ dùng từ khi nào; thường được kể là định hình qua thoại phim và phim truyền hình.", "de": "Redewendung aus 작업 (''Arbeit'') und 걸다 (''in Gang setzen''). Das Standardwörterbuch führt 작업 nur als ''Arbeit verrichten''; diese romantische Bedeutung fehlt dort. Wann sie sich durchsetzte, ist ungeprüft; meist heißt es, sie habe sich über Film- und Seriendialoge etabliert."}'::jsonb, '제3자를 두고 ''쟤 작업 건다''처럼 관찰하듯 쓰는 일이 많다. 본인이 ''작업 건다''고 말하면 능글맞게 들리므로 농담조가 아니면 잘 쓰지 않는다.', '{"en": "Most often said about someone else, as an observation: ''쟤 작업 건다''. Saying it about yourself sounds smug, so people only do it as a joke.", "ja": "第三者について「あの子仕掛けてる」と観察するように使うことが多い。自分で「仕掛ける」と言うと図々しく聞こえるので、冗談でなければあまり使わない。", "es": "Se dice sobre todo de otra persona, como observación: ''쟤 작업 건다''. Decirlo de uno mismo suena chulesco, así que solo se hace en broma.", "vi": "Thường nói về người khác như một nhận xét: ''쟤 작업 건다''. Tự nói về mình nghe tự mãn nên chỉ dùng khi đùa.", "de": "Meist über andere gesagt, als Beobachtung: ''쟤 작업 건다''. Über sich selbst klingt es selbstgefällig, deshalb nur im Scherz."}'::jsonb, array['헌팅','플러팅','밀당'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "To make a move"}, {"lang": "🇯🇵 JA", "text": "口説きにかかる"}, {"lang": "🇨🇳 ZH", "text": "下手追求"}, {"lang": "🇻🇳 VI", "text": "Ra chiêu tán tỉnh"}, {"lang": "🇪🇸 ES", "text": "Lanzarse a alguien"}, {"lang": "🇩🇪 DE", "text": "Einen Vorstoß machen"}]'::jsonb, array[]::text[]),
('382', '플러팅', 'Peul-Reo-Ting', 'love', null, '은근한 말과 행동으로 호감을 흘리는 것', '{"en": "Dropping subtle hints that you''re interested", "ja": "それとなく好意をにおわせる言動", "es": "Insinuar interés con gestos y palabras", "vi": "Thả thính bằng lời nói và cử chỉ", "de": "Mit Worten und Gesten Interesse andeuten"}'::jsonb, '[플러팅]', '[{"type": "명사", "definition": "상대에게 호감이 있다는 신호를 가볍게 흘리는 말이나 행동. 고백처럼 확실히 말하지 않고 농담·칭찬·눈빛·가벼운 스킨십으로 은근히 표현하는 것이 핵심이다. 영어 flirting을 그대로 들여온 말로, 연애 예능을 통해 한국어에 자리 잡았다.", "definition_i18n": {"en": "Words or actions that lightly signal you''re interested. The point is that it stays short of a confession — jokes, compliments, eye contact, a light touch. Borrowed straight from English ''flirting'' and settled into Korean through dating reality shows.", "ja": "相手に好意があるという合図を軽く出す言動。告白のようにはっきり言わず、冗談・褒め言葉・視線・軽いスキンシップでそれとなく示すのが肝。英語のflirtingをそのまま取り入れた語で、恋愛リアリティ番組を通じて韓国語に定着した。", "es": "Palabras o gestos que insinúan interés sin llegar a declararse: bromas, piropos, miradas, algún roce. Tomado tal cual del inglés ''flirting'' y asentado en coreano a través de los realities de citas.", "vi": "Lời nói hay hành động thả nhẹ tín hiệu thích ai đó. Điểm mấu chốt là chưa tới mức tỏ tình — đùa giỡn, khen, ánh mắt, chạm nhẹ. Mượn thẳng từ ''flirting'' tiếng Anh và vào tiếng Hàn qua các show hẹn hò.", "de": "Worte oder Gesten, die leicht Interesse signalisieren — Witze, Komplimente, Blicke, eine flüchtige Berührung, aber eben kein Geständnis. Direkt aus dem englischen ''flirting'' übernommen und über Dating-Realityshows im Koreanischen angekommen."}, "examples": [{"kor": "그거 그냥 친절한 거야, 플러팅이야?", "eng": "Is that just being nice, or is that flirting?", "ja": "それ、ただ親切なだけ? それともフラーティング?", "es": "¿Eso es solo amabilidad o está flirteando?", "vi": "Cái đó là tử tế thôi hay là thả thính vậy?", "de": "Ist das nur nett gemeint oder ist das schon Flirten?"}]}]'::jsonb, '영어 flirting을 음차한 외래어다. 위키백과는 어원을 ''날갯짓''을 뜻하는 fluttering 계열로 설명한다. 한국에서는 2020년대 연애 리얼리티 프로그램에서 출연자와 자막이 자주 쓰면서 일상어로 퍼졌다.', '{"en": "A transliteration of English ''flirting''. Wikipedia traces the English word to ''fluttering'', the flapping of wings. In Korea it spread into everyday speech in the 2020s as dating reality shows used it in dialogue and subtitles.", "ja": "英語flirtingの音写。ウィキペディアは語源を「羽ばたき」を意味するfluttering系と説明する。韓国では2020年代の恋愛リアリティ番組で出演者と字幕が多用し、日常語として広まった。", "es": "Transliteración del inglés ''flirting''. La Wikipedia remonta la palabra inglesa a ''fluttering'', el aleteo. En Corea se extendió al habla cotidiana en los 2020 por su uso en diálogos y subtítulos de realities de citas.", "vi": "Phiên âm từ ''flirting'' tiếng Anh. Wikipedia truy nguyên từ tiếng Anh về ''fluttering'', tiếng vỗ cánh. Ở Hàn, từ này vào đời sống thập niên 2020 khi các show hẹn hò dùng nhiều trong thoại và phụ đề.", "de": "Transliteration des englischen ''flirting''. Wikipedia führt das englische Wort auf ''fluttering'', das Flattern, zurück. In Korea kam es in den 2020ern in die Alltagssprache, weil Dating-Realityshows es in Dialogen und Untertiteln nutzten."}'::jsonb, '''플러팅하다'', ''플러팅 받았다''처럼 쓴다. 상대가 의도했는지 애매할 때 친구에게 물어보는 맥락에서 특히 많이 나온다.', '{"en": "Used as 플러팅하다 (to flirt) and 플러팅 받았다 (to be flirted with). It comes up most when you''re unsure whether the other person meant it and you''re asking a friend.", "ja": "「플러팅하다」「플러팅 받았다」のように使う。相手が意図したのか曖昧なときに友達に聞く文脈で特によく出る。", "es": "Se usa como 플러팅하다 (flirtear) y 플러팅 받았다 (que te flirteen). Aparece sobre todo cuando no sabes si iba en serio y se lo preguntas a un amigo.", "vi": "Dùng như 플러팅하다 (thả thính) và 플러팅 받았다 (bị thả thính). Hay xuất hiện nhất khi không chắc đối phương có ý gì và đi hỏi bạn bè.", "de": "Als 플러팅하다 (flirten) und 플러팅 받았다 (angeflirtet werden). Am häufigsten, wenn man unsicher ist, ob es so gemeint war, und Freunde fragt."}'::jsonb, array['썸','작업 걸다','그린라이트'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Flirting"}, {"lang": "🇯🇵 JA", "text": "フラーティング"}, {"lang": "🇨🇳 ZH", "text": "调情、示好"}, {"lang": "🇻🇳 VI", "text": "Thả thính"}, {"lang": "🇪🇸 ES", "text": "Flirtear"}, {"lang": "🇩🇪 DE", "text": "Flirten"}]'::jsonb, array[]::text[]),
('383', '애프터', 'Ae-Peu-Teo', 'love', null, '소개팅 뒤 다시 만나자고 하는 두 번째 약속', '{"en": "The second date you ask for after a set-up", "ja": "お見合い後にもう一度会おうと誘う二度目の約束", "es": "La segunda cita que pides tras una cita concertada", "vi": "Buổi hẹn thứ hai sau lần xem mắt", "de": "Das zweite Treffen nach einem vermittelten Date"}'::jsonb, '[애프터]', '[{"type": "명사", "definition": "소개팅에서 만난 뒤 다시 보자고 청하는 두 번째 만남. 영어 after에서 왔지만 영어에는 이런 명사 용법이 없는 콩글리시다. 첫 만남이 잘됐는지를 가늠하는 기준으로 통해서, ''애프터 신청''과 ''애프터 거절''이 한 세트로 쓰인다.", "definition_i18n": {"en": "The follow-up date you ask for after a set-up. From English ''after'', though English has no such noun — it''s Konglish. It works as the measure of whether the first meeting went well, so 애프터 신청 (asking for one) and 애프터 거절 (turning one down) come as a pair.", "ja": "お見合いで会った後、もう一度会おうと申し込む二度目の約束。英語afterから来ているが英語にこの名詞用法はなく韓国式英語。初対面がうまくいったかの目安とされ、「애프터 신청」と「애프터 거절」が一組で使われる。", "es": "La segunda cita que pides tras conocer a alguien en una cita concertada. Del inglés ''after'', aunque en inglés no existe ese uso como sustantivo: es konglish. Funciona como medida de si la primera cita fue bien, y van juntos 애프터 신청 (pedirla) y 애프터 거절 (rechazarla).", "vi": "Buổi hẹn thứ hai xin gặp lại sau lần xem mắt. Từ ''after'' tiếng Anh nhưng tiếng Anh không dùng như danh từ này — Konglish. Được xem là thước đo lần gặp đầu có ổn không, nên 애프터 신청 (xin hẹn) và 애프터 거절 (từ chối) đi thành cặp.", "de": "Das Folgetreffen, um das man nach einem vermittelten Date bittet. Von englisch ''after'', obwohl es dieses Substantiv im Englischen nicht gibt — Konglisch. Es gilt als Maßstab, ob das erste Treffen gut lief; 애프터 신청 (darum bitten) und 애프터 거절 (ablehnen) gehören zusammen."}, "examples": [{"kor": "어제 소개팅 어땠어? 애프터 들어왔어?", "eng": "How was the set-up yesterday? Did they ask you out again?", "ja": "昨日のお見合いどうだった? 二度目の誘い来た?", "es": "¿Qué tal la cita de ayer? ¿Te pidieron una segunda?", "vi": "Buổi xem mắt hôm qua sao rồi? Có xin hẹn lần hai không?", "de": "Wie war das Date gestern? Kam eine Anfrage fürs zweite Treffen?"}]}]'::jsonb, '영어 after를 명사로 쓴 콩글리시로, 소개팅 문화와 함께 굳었다. 표준국어대사전에는 등재돼 있지 않다. 언제부터 이 뜻으로 쓰였는지 특정하는 출처는 확인되지 않았다.', '{"en": "Konglish that turns English ''after'' into a noun, settled in alongside set-up dating culture. It is not in the standard Korean dictionary, and no source pins down when it took this sense.", "ja": "英語afterを名詞として使う韓国式英語で、お見合い文化とともに定着した。標準国語大辞典には未収録。いつからこの意味になったかを特定する出典は確認されていない。", "es": "Konglish que convierte el inglés ''after'' en sustantivo, asentado junto a la cultura de las citas concertadas. No figura en el diccionario estándar y ninguna fuente fija cuándo tomó este sentido.", "vi": "Konglish biến ''after'' tiếng Anh thành danh từ, định hình cùng văn hóa xem mắt. Không có trong từ điển chuẩn và chưa nguồn nào xác định từ khi nào mang nghĩa này.", "de": "Konglisch, das englisch ''after'' zum Substantiv macht, etabliert mit der Kultur vermittelter Dates. Steht nicht im Standardwörterbuch; keine Quelle datiert, wann die Bedeutung entstand."}'::jsonb, '''애프터 신청하다'', ''애프터 받다'', ''애프터 없었다''처럼 쓴다. 소개팅 결과를 묻는 대화에서 거의 고정적으로 등장한다.', '{"en": "Used as 애프터 신청하다 (to ask for one), 애프터 받다 (to get one), 애프터 없었다 (there wasn''t one). It shows up almost every time someone asks how a set-up went.", "ja": "「애프터 신청하다」「애프터 받다」「애프터 없었다」のように使う。お見合いの結果を聞く会話ではほぼ決まって出てくる。", "es": "Se usa como 애프터 신청하다 (pedirla), 애프터 받다 (recibirla), 애프터 없었다 (no la hubo). Aparece casi siempre que alguien pregunta cómo fue una cita concertada.", "vi": "Dùng như 애프터 신청하다 (xin hẹn), 애프터 받다 (được xin hẹn), 애프터 없었다 (không có). Gần như luôn xuất hiện khi ai đó hỏi buổi xem mắt thế nào.", "de": "Als 애프터 신청하다 (darum bitten), 애프터 받다 (eine bekommen), 애프터 없었다 (es gab keine). Kommt fast immer vor, wenn jemand fragt, wie ein Date lief."}'::jsonb, array['인만추','그린라이트','썸'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "A second date"}, {"lang": "🇯🇵 JA", "text": "二度目のデートの誘い"}, {"lang": "🇨🇳 ZH", "text": "第二次约会邀请"}, {"lang": "🇻🇳 VI", "text": "Hẹn lần hai"}, {"lang": "🇪🇸 ES", "text": "Segunda cita"}, {"lang": "🇩🇪 DE", "text": "Zweites Date"}]'::jsonb, array[]::text[]),
('384', '짝남', 'Jjak-Nam', 'love', null, '내가 짝사랑하는 남자', '{"en": "The guy you have a one-sided crush on", "ja": "片思いしている男性", "es": "El chico por quien suspiras en secreto", "vi": "Chàng trai mà mình thầm thích", "de": "Der Typ, in den man heimlich verliebt ist"}'::jsonb, '[짱남]', '[{"type": "명사", "definition": "내가 혼자 좋아하고 있는 남자. ''짝사랑''의 ''짝''에 성별을 붙여 줄인 말이다. 상대는 대개 내 마음을 모르는 상태이며, 학교·직장·동아리처럼 자주 마주치는 사이에서 쓰는 일이 많다. 반대쪽은 ''짝녀''라고 한다.", "definition_i18n": {"en": "The guy you''re quietly in love with. Built from 짝 (of 짝사랑, ''one-sided love'') plus a gender marker. Usually they have no idea, and the word comes up about someone you see regularly — at school, at work, in a club. The counterpart is 짝녀.", "ja": "自分だけが好きでいる男性。「짝사랑(片思い)」の「짝」に性別を付けて略した語。相手はたいてい気づいておらず、学校・職場・サークルなど頻繁に会う相手について使うことが多い。対になる語は「짝녀」。", "es": "El chico de quien estás enamorado en silencio. Se forma con 짝 (de 짝사랑, ''amor no correspondido'') más la marca de género. Normalmente la otra persona no lo sabe, y se usa para alguien a quien ves a menudo: clase, trabajo, un club. El opuesto es 짝녀.", "vi": "Chàng trai mà mình thầm thương. Ghép 짝 (trong 짝사랑, ''yêu đơn phương'') với ký hiệu giới tính. Thường đối phương không hề biết, và từ này hay dùng cho người mình gặp thường xuyên — ở trường, chỗ làm, câu lạc bộ. Từ đối lại là 짝녀.", "de": "Der Typ, in den man still verliebt ist. Gebildet aus 짝 (von 짝사랑, ''unerwiderte Liebe'') plus Geschlechtsmarker. Meist ahnt die Person nichts, und das Wort fällt über jemanden, den man regelmäßig sieht — in der Schule, im Job, im Verein. Das Gegenstück ist 짝녀."}, "examples": [{"kor": "내 짝남이 오늘 나한테 먼저 말 걸었어!", "eng": "My crush actually spoke to me first today!", "ja": "片思いの彼が今日私から先に話しかけてくれた!", "es": "¡Hoy mi crush me habló primero!", "vi": "Hôm nay crush chủ động bắt chuyện với tao!", "de": "Mein Schwarm hat mich heute zuerst angesprochen!"}]}]'::jsonb, '''짝사랑''에서 ''짝''만 떼어 ''남/녀''를 붙인 줄임말이다. 온라인 커뮤니티와 SNS에서 자연스럽게 퍼진 말로, 언제 어디서 처음 쓰였는지는 어느 출처도 특정하지 않는다. 국어사전형 사이트에는 표제어로 올라 있다.', '{"en": "A clipping that takes 짝 from 짝사랑 and adds a gender suffix. It spread organically through online communities and social media; no source pins down when or where it was first used. Dictionary-style sites do carry it as a headword.", "ja": "「짝사랑」から「짝」だけを取り「남/녀」を付けた略語。オンラインコミュニティやSNSで自然に広まった語で、いつどこで最初に使われたかを特定する出典はない。国語辞典型サイトには見出し語として載っている。", "es": "Recorte que toma 짝 de 짝사랑 y añade el sufijo de género. Se difundió de forma natural por foros y redes; ninguna fuente fija cuándo o dónde se usó primero. Los sitios tipo diccionario sí lo recogen como entrada.", "vi": "Dạng rút gọn lấy 짝 từ 짝사랑 rồi thêm hậu tố giới tính. Lan tự nhiên qua cộng đồng mạng và mạng xã hội; không nguồn nào xác định dùng lần đầu khi nào, ở đâu. Các trang kiểu từ điển có ghi làm mục từ.", "de": "Eine Kürzung, die 짝 aus 짝사랑 nimmt und ein Geschlechtssuffix anhängt. Sie verbreitete sich organisch über Online-Foren und Social Media; keine Quelle datiert die erste Verwendung. Wörterbuchartige Seiten führen sie als Stichwort."}'::jsonb, '친구에게 마음을 털어놓을 때 ''내 짝남/짝녀''처럼 소유격을 붙여 쓴다. 사귀는 사이가 아니라 아직 혼자만의 마음이라는 점이 핵심이라, 사귀기 시작하면 더 이상 쓰지 않는다.', '{"en": "Said with a possessive when confiding in a friend: 내 짝남 / 내 짝녀. The point is that it''s still one-sided — once you start dating, the word stops applying.", "ja": "友達に打ち明けるとき「私の짝남/짝녀」と所有格を付けて使う。まだ片思いだという点が肝で、付き合い始めたらもう使わない。", "es": "Se dice con posesivo al confiarse a un amigo: 내 짝남 / 내 짝녀. La clave es que sigue siendo unilateral: en cuanto empezáis a salir, deja de usarse.", "vi": "Nói kèm sở hữu khi tâm sự với bạn: 내 짝남 / 내 짝녀. Điểm chính là vẫn đơn phương — bắt đầu yêu rồi thì không dùng nữa.", "de": "Mit Possessiv, wenn man sich Freunden anvertraut: 내 짝남 / 내 짝녀. Entscheidend ist, dass es einseitig bleibt — sobald man zusammen ist, passt das Wort nicht mehr."}'::jsonb, array['짝녀','썸','금사빠'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "The guy you have a crush on"}, {"lang": "🇯🇵 JA", "text": "片思いの彼"}, {"lang": "🇨🇳 ZH", "text": "暗恋的男生"}, {"lang": "🇻🇳 VI", "text": "Crush nam"}, {"lang": "🇪🇸 ES", "text": "El chico que te gusta"}, {"lang": "🇩🇪 DE", "text": "Der heimliche Schwarm (m)"}]'::jsonb, array[]::text[]),
('385', '짝녀', 'Jjak-Nyeo', 'love', null, '내가 짝사랑하는 여자', '{"en": "The girl you have a one-sided crush on", "ja": "片思いしている女性", "es": "La chica por quien suspiras en secreto", "vi": "Cô gái mà mình thầm thích", "de": "Das Mädchen, in das man heimlich verliebt ist"}'::jsonb, '[짱녀]', '[{"type": "명사", "definition": "내가 혼자 좋아하고 있는 여자. ''짝사랑''의 ''짝''에 성별을 붙여 줄인 말이다. 상대는 대개 내 마음을 모르는 상태이며, 학교·직장·동아리처럼 자주 마주치는 사이에서 쓰는 일이 많다. 반대쪽은 ''짝남''이라고 한다.", "definition_i18n": {"en": "The girl you''re quietly in love with. Built from 짝 (of 짝사랑, ''one-sided love'') plus a gender marker. Usually they have no idea, and the word comes up about someone you see regularly — at school, at work, in a club. The counterpart is 짝남.", "ja": "自分だけが好きでいる女性。「짝사랑(片思い)」の「짝」に性別を付けて略した語。相手はたいてい気づいておらず、学校・職場・サークルなど頻繁に会う相手について使うことが多い。対になる語は「짝남」。", "es": "La chica de quien estás enamorado en silencio. Se forma con 짝 (de 짝사랑, ''amor no correspondido'') más la marca de género. Normalmente la otra persona no lo sabe, y se usa para alguien a quien ves a menudo: clase, trabajo, un club. El opuesto es 짝남.", "vi": "Cô gái mà mình thầm thương. Ghép 짝 (trong 짝사랑, ''yêu đơn phương'') với ký hiệu giới tính. Thường đối phương không hề biết, và từ này hay dùng cho người mình gặp thường xuyên — ở trường, chỗ làm, câu lạc bộ. Từ đối lại là 짝남.", "de": "Das Mädchen, in das man still verliebt ist. Gebildet aus 짝 (von 짝사랑, ''unerwiderte Liebe'') plus Geschlechtsmarker. Meist ahnt die Person nichts, und das Wort fällt über jemanden, den man regelmäßig sieht — in der Schule, im Job, im Verein. Das Gegenstück ist 짝남."}, "examples": [{"kor": "짝녀한테 고백할까 말까 계속 고민 중이야.", "eng": "I keep going back and forth on whether to tell my crush.", "ja": "片思いの彼女に告白するか、ずっと迷ってる。", "es": "Llevo días dudando si confesarme a mi crush.", "vi": "Tao cứ đắn đo mãi có nên tỏ tình với crush không.", "de": "Ich überlege ständig, ob ich es meinem Schwarm sagen soll."}]}]'::jsonb, '''짝사랑''에서 ''짝''만 떼어 ''남/녀''를 붙인 줄임말이다. 온라인 커뮤니티와 SNS에서 자연스럽게 퍼진 말로, 언제 어디서 처음 쓰였는지는 어느 출처도 특정하지 않는다. 국어사전형 사이트에는 표제어로 올라 있다.', '{"en": "A clipping that takes 짝 from 짝사랑 and adds a gender suffix. It spread organically through online communities and social media; no source pins down when or where it was first used. Dictionary-style sites do carry it as a headword.", "ja": "「짝사랑」から「짝」だけを取り「남/녀」を付けた略語。オンラインコミュニティやSNSで自然に広まった語で、いつどこで最初に使われたかを特定する出典はない。国語辞典型サイトには見出し語として載っている。", "es": "Recorte que toma 짝 de 짝사랑 y añade el sufijo de género. Se difundió de forma natural por foros y redes; ninguna fuente fija cuándo o dónde se usó primero. Los sitios tipo diccionario sí lo recogen como entrada.", "vi": "Dạng rút gọn lấy 짝 từ 짝사랑 rồi thêm hậu tố giới tính. Lan tự nhiên qua cộng đồng mạng và mạng xã hội; không nguồn nào xác định dùng lần đầu khi nào, ở đâu. Các trang kiểu từ điển có ghi làm mục từ.", "de": "Eine Kürzung, die 짝 aus 짝사랑 nimmt und ein Geschlechtssuffix anhängt. Sie verbreitete sich organisch über Online-Foren und Social Media; keine Quelle datiert die erste Verwendung. Wörterbuchartige Seiten führen sie als Stichwort."}'::jsonb, '친구에게 마음을 털어놓을 때 ''내 짝남/짝녀''처럼 소유격을 붙여 쓴다. 사귀는 사이가 아니라 아직 혼자만의 마음이라는 점이 핵심이라, 사귀기 시작하면 더 이상 쓰지 않는다.', '{"en": "Said with a possessive when confiding in a friend: 내 짝남 / 내 짝녀. The point is that it''s still one-sided — once you start dating, the word stops applying.", "ja": "友達に打ち明けるとき「私の짝남/짝녀」と所有格を付けて使う。まだ片思いだという点が肝で、付き合い始めたらもう使わない。", "es": "Se dice con posesivo al confiarse a un amigo: 내 짝남 / 내 짝녀. La clave es que sigue siendo unilateral: en cuanto empezáis a salir, deja de usarse.", "vi": "Nói kèm sở hữu khi tâm sự với bạn: 내 짝남 / 내 짝녀. Điểm chính là vẫn đơn phương — bắt đầu yêu rồi thì không dùng nữa.", "de": "Mit Possessiv, wenn man sich Freunden anvertraut: 내 짝남 / 내 짝녀. Entscheidend ist, dass es einseitig bleibt — sobald man zusammen ist, passt das Wort nicht mehr."}'::jsonb, array['짝남','썸','금사빠'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "The girl you have a crush on"}, {"lang": "🇯🇵 JA", "text": "片思いの彼女"}, {"lang": "🇨🇳 ZH", "text": "暗恋的女生"}, {"lang": "🇻🇳 VI", "text": "Crush nữ"}, {"lang": "🇪🇸 ES", "text": "La chica que te gusta"}, {"lang": "🇩🇪 DE", "text": "Der heimliche Schwarm (w)"}]'::jsonb, array[]::text[]),
('386', '품절남', 'Pum-Jeol-Nam', 'love', null, '이미 임자가 있는 남자', '{"en": "A man who''s already taken", "ja": "すでに相手がいる男性", "es": "Un hombre que ya está pillado", "vi": "Người đàn ông đã có chủ", "de": "Ein Mann, der schon vergeben ist"}'::jsonb, '[품절람]', '[{"type": "명사", "definition": "결혼했거나 사귀는 사람이 있어서 더는 연애 상대가 될 수 없는 남자. 가게에서 물건이 다 팔렸다는 ''품절''을 사람에게 옮겨 붙인 농담조 표현이다. 인기 있는 사람이 임자가 생겼을 때 아쉬움 섞어 쓰는 일이 많고, 특히 연예인 결혼 소식에 언론이 즐겨 쓴다. 반대쪽은 ''품절녀''라고 한다.", "definition_i18n": {"en": "A man who is married or taken and therefore off the market. It borrows 품절, the shop sign for ''sold out'', and pins it on a person — a joke, usually said with a touch of regret when someone popular is spoken for. Korean entertainment press reaches for it whenever a celebrity marries. The counterpart is 품절녀.", "ja": "結婚しているか交際相手がいて、もう恋愛対象になれない男性。店の「品切れ」を人に転用したおどけた表現。人気のある人に相手ができたときに惜しさ混じりで使うことが多く、芸能人の結婚報道で特によく使われる。対になる語は「품절녀」。", "es": "Un hombre que está casado o emparejado y por tanto fuera del mercado. Toma 품절, el cartel de ''agotado'' de las tiendas, y lo aplica a una persona: es una broma, dicha con cierta pena cuando alguien popular ya tiene pareja. La prensa del corazón lo usa en cada boda de famosos. El opuesto es 품절녀.", "vi": "Người đàn ông đã kết hôn hoặc đang yêu nên không còn là đối tượng hẹn hò. Mượn chữ 품절 (''hết hàng'') trong cửa hàng gán cho con người — một cách nói đùa, thường kèm chút tiếc nuối khi người nổi tiếng đã có chủ. Báo giải trí Hàn dùng mỗi khi có sao cưới. Từ đối lại là 품절녀.", "de": "Ein Mann, der verheiratet oder vergeben und damit vom Markt ist. Es überträgt 품절, das Ladenschild für ''ausverkauft'', auf Menschen — ein Scherz, meist mit einem Anflug von Bedauern, wenn jemand Begehrtes vergeben ist. Die Klatschpresse greift bei jeder Promi-Hochzeit dazu. Das Gegenstück ist 품절녀."}, "examples": [{"kor": "우리 과 인기남도 드디어 품절남 됐대.", "eng": "Even the most popular guy in our department is finally off the market.", "ja": "うちの学科の人気者もついに品切れになったって。", "es": "Hasta el chico más popular de la facultad ya está pillado.", "vi": "Anh hot nhất khoa tao cuối cùng cũng có chủ rồi.", "de": "Sogar der beliebteste Typ im Studiengang ist jetzt vergeben."}]}]'::jsonb, '가게에서 물건이 다 팔렸다는 뜻의 ''품절(品切)''을 사람에게 옮겨 쓴 말이다. 연예인 결혼 기사에서 자주 쓰이며 굳었고, 표준국어대사전에는 등재돼 있지 않다. 누가 처음 이렇게 썼는지는 확인되지 않는다.', '{"en": "It transfers 품절, ''sold out'' in a shop, onto people. It hardened through entertainment reporting on celebrity marriages and is not in the standard Korean dictionary. Who used it this way first is unverified.", "ja": "店で商品が売り切れた意味の「품절(品切れ)」を人に転用した語。芸能人の結婚記事で多用されて定着し、標準国語大辞典には未収録。誰が最初にこう使ったかは未確認。", "es": "Traslada 품절, ''agotado'' en una tienda, a las personas. Se fijó a través de las noticias sobre bodas de famosos y no está en el diccionario estándar. Quién lo usó así primero no está verificado.", "vi": "Chuyển chữ 품절 (''hết hàng'' ở cửa hàng) sang chỉ người. Định hình qua tin bài về đám cưới người nổi tiếng và không có trong từ điển chuẩn. Ai dùng đầu tiên thì chưa xác minh.", "de": "Überträgt 품절, im Laden ''ausverkauft'', auf Menschen. Es verfestigte sich über die Berichterstattung zu Promi-Hochzeiten und steht nicht im Standardwörterbuch. Wer es zuerst so verwendete, ist ungeprüft."}'::jsonb, '농담조라 친한 사이나 연예인 이야기에서 쓴다. 당사자 앞에서 직접 말하면 결혼·연애 여부를 들춰내는 셈이라 실례가 될 수 있다.', '{"en": "It''s a joke, so it belongs among friends or in celebrity talk. Said to someone''s face it drags their marital or dating status into the open, which can land as rude.", "ja": "おどけた表現なので、親しい間柄や芸能人の話で使う。本人の前で直接言うと結婚・交際の有無を暴くことになり失礼になりうる。", "es": "Es una broma, así que va entre amigos o hablando de famosos. Dicho a la cara saca a la luz si esa persona está casada o emparejada, y puede resultar grosero.", "vi": "Là cách nói đùa nên dùng giữa bạn bè hoặc khi bàn về người nổi tiếng. Nói thẳng trước mặt là phơi bày chuyện hôn nhân, yêu đương của người ta, dễ thành bất lịch sự.", "de": "Es ist ein Scherz und gehört unter Freunde oder in Promi-Gespräche. Direkt ins Gesicht gesagt legt es den Beziehungsstatus offen und kann unhöflich wirken."}'::jsonb, array['품절녀','돌싱','썸'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "A man who''s taken"}, {"lang": "🇯🇵 JA", "text": "既婚・彼女持ちの男性"}, {"lang": "🇨🇳 ZH", "text": "名花有主的男人"}, {"lang": "🇻🇳 VI", "text": "Đàn ông đã có chủ"}, {"lang": "🇪🇸 ES", "text": "Hombre ya pillado"}, {"lang": "🇩🇪 DE", "text": "Vergebener Mann"}]'::jsonb, array[]::text[]),
('387', '품절녀', 'Pum-Jeol-Nyeo', 'love', null, '이미 임자가 있는 여자', '{"en": "A woman who''s already taken", "ja": "すでに相手がいる女性", "es": "Una mujer que ya está pillada", "vi": "Người phụ nữ đã có chủ", "de": "Eine Frau, die schon vergeben ist"}'::jsonb, '[품절려]', '[{"type": "명사", "definition": "결혼했거나 사귀는 사람이 있어서 더는 연애 상대가 될 수 없는 여자. 가게에서 물건이 다 팔렸다는 ''품절''을 사람에게 옮겨 붙인 농담조 표현이다. 인기 있는 사람이 임자가 생겼을 때 아쉬움 섞어 쓰는 일이 많고, 특히 연예인 결혼 소식에 언론이 즐겨 쓴다. 반대쪽은 ''품절남''이라고 한다.", "definition_i18n": {"en": "A woman who is married or taken and therefore off the market. It borrows 품절, the shop sign for ''sold out'', and pins it on a person — a joke, usually said with a touch of regret when someone popular is spoken for. Korean entertainment press reaches for it whenever a celebrity marries. The counterpart is 품절남.", "ja": "結婚しているか交際相手がいて、もう恋愛対象になれない女性。店の「品切れ」を人に転用したおどけた表現。人気のある人に相手ができたときに惜しさ混じりで使うことが多く、芸能人の結婚報道で特によく使われる。対になる語は「품절남」。", "es": "Una mujer que está casada o emparejada y por tanto fuera del mercado. Toma 품절, el cartel de ''agotado'' de las tiendas, y lo aplica a una persona: es una broma, dicha con cierta pena cuando alguien popular ya tiene pareja. La prensa del corazón lo usa en cada boda de famosos. El opuesto es 품절남.", "vi": "Người phụ nữ đã kết hôn hoặc đang yêu nên không còn là đối tượng hẹn hò. Mượn chữ 품절 (''hết hàng'') trong cửa hàng gán cho con người — một cách nói đùa, thường kèm chút tiếc nuối khi người nổi tiếng đã có chủ. Báo giải trí Hàn dùng mỗi khi có sao cưới. Từ đối lại là 품절남.", "de": "Eine Frau, die verheiratet oder vergeben und damit vom Markt ist. Es überträgt 품절, das Ladenschild für ''ausverkauft'', auf Menschen — ein Scherz, meist mit einem Anflug von Bedauern, wenn jemand Begehrtes vergeben ist. Die Klatschpresse greift bei jeder Promi-Hochzeit dazu. Das Gegenstück ist 품절남."}, "examples": [{"kor": "결혼 발표 나자마자 기사 제목이 전부 ''품절녀''더라.", "eng": "The moment she announced the wedding, every headline called her ''off the market''.", "ja": "結婚発表の途端、記事の見出しが全部「品切れ女」だった。", "es": "En cuanto anunció la boda, todos los titulares la llamaban ''ya pillada''.", "vi": "Vừa công bố cưới là mọi tiêu đề đều gọi cô ấy là ''đã có chủ''.", "de": "Kaum war die Hochzeit verkündet, nannten sie alle Schlagzeilen ''vergeben''."}]}]'::jsonb, '가게에서 물건이 다 팔렸다는 뜻의 ''품절(品切)''을 사람에게 옮겨 쓴 말이다. 연예인 결혼 기사에서 자주 쓰이며 굳었고, 표준국어대사전에는 등재돼 있지 않다. 누가 처음 이렇게 썼는지는 확인되지 않는다.', '{"en": "It transfers 품절, ''sold out'' in a shop, onto people. It hardened through entertainment reporting on celebrity marriages and is not in the standard Korean dictionary. Who used it this way first is unverified.", "ja": "店で商品が売り切れた意味の「품절(品切れ)」を人に転用した語。芸能人の結婚記事で多用されて定着し、標準国語大辞典には未収録。誰が最初にこう使ったかは未確認。", "es": "Traslada 품절, ''agotado'' en una tienda, a las personas. Se fijó a través de las noticias sobre bodas de famosos y no está en el diccionario estándar. Quién lo usó así primero no está verificado.", "vi": "Chuyển chữ 품절 (''hết hàng'' ở cửa hàng) sang chỉ người. Định hình qua tin bài về đám cưới người nổi tiếng và không có trong từ điển chuẩn. Ai dùng đầu tiên thì chưa xác minh.", "de": "Überträgt 품절, im Laden ''ausverkauft'', auf Menschen. Es verfestigte sich über die Berichterstattung zu Promi-Hochzeiten und steht nicht im Standardwörterbuch. Wer es zuerst so verwendete, ist ungeprüft."}'::jsonb, '농담조라 친한 사이나 연예인 이야기에서 쓴다. 당사자 앞에서 직접 말하면 결혼·연애 여부를 들춰내는 셈이라 실례가 될 수 있다.', '{"en": "It''s a joke, so it belongs among friends or in celebrity talk. Said to someone''s face it drags their marital or dating status into the open, which can land as rude.", "ja": "おどけた表現なので、親しい間柄や芸能人の話で使う。本人の前で直接言うと結婚・交際の有無を暴くことになり失礼になりうる。", "es": "Es una broma, así que va entre amigos o hablando de famosos. Dicho a la cara saca a la luz si esa persona está casada o emparejada, y puede resultar grosero.", "vi": "Là cách nói đùa nên dùng giữa bạn bè hoặc khi bàn về người nổi tiếng. Nói thẳng trước mặt là phơi bày chuyện hôn nhân, yêu đương của người ta, dễ thành bất lịch sự.", "de": "Es ist ein Scherz und gehört unter Freunde oder in Promi-Gespräche. Direkt ins Gesicht gesagt legt es den Beziehungsstatus offen und kann unhöflich wirken."}'::jsonb, array['품절남','돌싱','썸'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "A woman who''s taken"}, {"lang": "🇯🇵 JA", "text": "既婚・彼氏持ちの女性"}, {"lang": "🇨🇳 ZH", "text": "名草有主的女人"}, {"lang": "🇻🇳 VI", "text": "Phụ nữ đã có chủ"}, {"lang": "🇪🇸 ES", "text": "Mujer ya pillada"}, {"lang": "🇩🇪 DE", "text": "Vergebene Frau"}]'::jsonb, array[]::text[]),
('388', '읽씹', 'Ilk-Ssip', 'daily', 'love', '메시지를 읽고도 답을 안 하는 것', '{"en": "Reading a message and never replying", "ja": "メッセージを読んでも返事をしないこと", "es": "Leer un mensaje y no contestar", "vi": "Đọc tin nhắn rồi lơ luôn", "de": "Eine Nachricht lesen und nicht antworten"}'::jsonb, '[익씹]', '[{"type": "명사", "definition": "''읽고 씹다''의 준말. 카카오톡에서 메시지를 읽어 숫자 ''1''이 사라졌는데도 답장을 하지 않는 것을 말한다. 상대는 읽음 표시로 확인했다는 걸 알기 때문에 무시당했다는 느낌이 분명하게 남는다. 답장 대신 침묵을 고르는 행동이라 연애에서는 관계가 식었다는 신호로 읽힌다.", "definition_i18n": {"en": "Short for 읽고 씹다, ''read it and blank it''. On KakaoTalk the unread marker disappears once you open a message, so ignoring it afterwards is visible to the sender — which is exactly what makes it sting. In dating it reads as a sign that interest has cooled.", "ja": "「읽고 씹다(読んで無視する)」の略。カカオトークでメッセージを開くと未読の「1」が消えるため、そのあと返さないと相手に見えてしまう。それが刺さる理由で、恋愛では気持ちが冷めた合図と読まれる。", "es": "Abreviatura de 읽고 씹다, ''leerlo y pasar''. En KakaoTalk la marca de no leído desaparece al abrir el mensaje, así que ignorarlo después queda a la vista del remitente, y por eso duele. En pareja se lee como que el interés se ha enfriado.", "vi": "Viết tắt của 읽고 씹다, ''đọc rồi lơ''. Trên KakaoTalk, dấu chưa đọc biến mất khi bạn mở tin, nên việc phớt lờ sau đó bị người gửi thấy rõ — chính điều đó khiến nó đau. Trong tình yêu, đây bị hiểu là dấu hiệu nguội lạnh.", "de": "Kurz für 읽고 씹다, ''lesen und ignorieren''. In KakaoTalk verschwindet die Ungelesen-Markierung beim Öffnen, das Ignorieren danach ist für den Absender also sichtbar — genau das trifft. In Beziehungen gilt es als Zeichen erkalteten Interesses."}, "examples": [{"kor": "어제 보낸 거 읽씹당해서 하루 종일 신경 쓰였어.", "eng": "They read what I sent yesterday and never replied — it bugged me all day.", "ja": "昨日送ったの読んで無視されて、一日中気になってた。", "es": "Leyó lo que le mandé ayer y no contestó; me tuvo todo el día pensando.", "vi": "Tin hôm qua bị đọc rồi lơ, tao nghĩ cả ngày.", "de": "Meine Nachricht von gestern wurde gelesen und nie beantwortet — hat mich den ganzen Tag beschäftigt."}]}]'::jsonb, '''읽고 씹다''를 두 글자로 줄인 말이다. 카카오톡의 읽음 표시(숫자 1) 기능이 있어야 성립하는 개념이라, 메신저 문화와 함께 굳었다. 여기서 ''씹다''는 무시한다는 뜻의 속어다.', '{"en": "A two-syllable clipping of 읽고 씹다. The concept only works because KakaoTalk shows a read marker, so it hardened alongside messenger culture. 씹다 here is slang for ignoring someone.", "ja": "「읽고 씹다」を二文字に略した語。カカオトークの既読表示(数字の1)があって初めて成り立つ概念で、メッセンジャー文化とともに定着した。ここでの「씹다」は無視するという意味の俗語。", "es": "Recorte de dos sílabas de 읽고 씹다. El concepto solo funciona porque KakaoTalk marca lo leído, así que cuajó con la cultura de la mensajería. 씹다 es aquí jerga para ignorar.", "vi": "Rút gọn hai âm tiết của 읽고 씹다. Khái niệm chỉ thành lập vì KakaoTalk hiển thị dấu đã đọc, nên nó định hình cùng văn hóa nhắn tin. 씹다 ở đây là tiếng lóng nghĩa phớt lờ.", "de": "Zweisilbige Kürzung von 읽고 씹다. Das Konzept funktioniert nur, weil KakaoTalk Gelesen-Markierungen zeigt, es verfestigte sich also mit der Messenger-Kultur. 씹다 ist hier Slang für ignorieren."}'::jsonb, '''읽씹하다''(내가 무시하다)와 ''읽씹당하다''(내가 무시당하다) 양쪽으로 쓴다. 가벼운 투정부터 진지한 서운함까지 폭넓게 쓰이지만, 대놓고 지적하면 상대를 몰아붙이는 말이 된다.', '{"en": "Used both ways: 읽씹하다 (to ignore) and 읽씹당하다 (to be ignored). It ranges from light complaining to real hurt, but pointing it out directly puts the other person on the spot.", "ja": "「읽씹하다」(自分が無視する)と「읽씹당하다」(無視される)の両方で使う。軽いぼやきから本気の寂しさまで幅広いが、面と向かって指摘すると相手を追い詰める言葉になる。", "es": "Se usa en ambos sentidos: 읽씹하다 (ignorar) y 읽씹당하다 (que te ignoren). Va de la queja ligera al dolor real, pero señalarlo de frente pone al otro contra las cuerdas.", "vi": "Dùng cả hai chiều: 읽씹하다 (mình lơ) và 읽씹당하다 (bị lơ). Từ càu nhàu nhẹ đến tổn thương thật, nhưng nói thẳng ra là dồn đối phương vào thế bí.", "de": "In beide Richtungen: 읽씹하다 (ignorieren) und 읽씹당하다 (ignoriert werden). Von leichtem Nörgeln bis echter Verletzung — direkt angesprochen setzt es das Gegenüber aber unter Druck."}'::jsonb, array['안읽씹','잠수이별','손절'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Read and left on seen"}, {"lang": "🇯🇵 JA", "text": "既読スルー"}, {"lang": "🇨🇳 ZH", "text": "已读不回"}, {"lang": "🇻🇳 VI", "text": "Đọc không rep"}, {"lang": "🇪🇸 ES", "text": "Dejar en visto"}, {"lang": "🇩🇪 DE", "text": "Gelesen, nicht geantwortet"}]'::jsonb, array[]::text[]),
('389', '안읽씹', 'An-Ilk-Ssip', 'daily', 'love', '알림으로 보고도 일부러 안 읽고 무시하는 것', '{"en": "Deliberately leaving a message unread", "ja": "通知で見ても、わざと開かず無視すること", "es": "Dejar un mensaje sin abrir a propósito", "vi": "Cố tình không mở tin nhắn để lơ", "de": "Eine Nachricht absichtlich ungelesen lassen"}'::jsonb, '[아닉씹]', '[{"type": "명사", "definition": "''안 읽고 씹다''의 준말. 알림창으로 내용을 확인하고도 채팅방에 들어가지 않아 숫자 ''1''을 남겨 둔 채 무시하는 것이다. 읽씹은 읽었다는 사실이라도 남지만 안읽씹은 그마저 없어서, 더 확실하게 거리를 두는 행동으로 받아들여진다.", "definition_i18n": {"en": "Short for 안 읽고 씹다, ''don''t even open it and blank it''. You read the preview in the notification but never enter the chat, so the unread marker stays. 읽씹 at least leaves proof you looked; this leaves nothing, so it reads as the firmer way of pushing someone away.", "ja": "「안 읽고 씹다(読まずに無視する)」の略。通知で内容を確認しながらトークルームに入らず、未読の「1」を残したまま無視すること。읽씹は読んだ事実だけは残るが、안읽씹はそれすらないので、より明確に距離を置く行動と受け取られる。", "es": "Abreviatura de 안 읽고 씹다, ''ni lo abras y pasa''. Lees la vista previa en la notificación pero no entras al chat, así que la marca de no leído se queda. 읽씹 al menos deja constancia de que miraste; esto no deja nada, y por eso se percibe como una forma más rotunda de alejarse.", "vi": "Viết tắt của 안 읽고 씹다, ''không mở mà lơ luôn''. Bạn đọc nội dung ở thông báo nhưng không vào phòng chat, nên dấu chưa đọc vẫn còn. 읽씹 ít ra còn để lại bằng chứng đã xem; cái này không để lại gì, nên bị coi là cách cắt đứt dứt khoát hơn.", "de": "Kurz für 안 읽고 씹다, ''gar nicht erst öffnen und ignorieren''. Man liest die Vorschau in der Benachrichtigung, betritt den Chat aber nie, sodass die Ungelesen-Markierung bleibt. 읽씹 hinterlässt immerhin den Beleg, dass man hingesehen hat; das hier hinterlässt nichts und gilt daher als der entschiedenere Rückzug."}, "examples": [{"kor": "읽씹도 아니고 안읽씹이면 진짜 끝난 거 아니야?", "eng": "Not even left on seen — left unopened? That''s really over, isn''t it?", "ja": "既読スルーどころか未読スルーって、もう完全に終わりじゃない?", "es": "Ni siquiera en visto, sin abrir. Eso ya se acabó, ¿no?", "vi": "Không phải đọc rồi lơ mà là không thèm mở luôn, vậy là hết thật rồi còn gì?", "de": "Nicht mal gelesen und ignoriert, sondern gar nicht geöffnet? Das ist doch endgültig vorbei."}]}]'::jsonb, '''읽씹''에서 파생해 ''안''을 앞에 붙인 말이다. 읽씹이 먼저 자리 잡은 뒤 그보다 더한 무시를 가리키려고 생겼다. 정확한 발생 시점을 특정하는 출처는 확인되지 않았다.', '{"en": "Derived from 읽씹 by prefixing 안 (''not''). It appeared after 읽씹 had settled, to name an even colder form of ignoring. No source pins down exactly when.", "ja": "「읽씹」から派生し、前に「안(〜しない)」を付けた語。읽씹が定着した後、それ以上の無視を指すために生まれた。正確な発生時期を特定する出典は確認されていない。", "es": "Derivado de 읽씹 anteponiendo 안 (''no''). Surgió después de que 읽씹 se asentara, para nombrar una forma aún más fría de ignorar. Ninguna fuente fija cuándo exactamente.", "vi": "Phái sinh từ 읽씹 bằng cách thêm 안 (''không'') phía trước. Xuất hiện sau khi 읽씹 đã phổ biến, để gọi mức phớt lờ còn lạnh hơn. Chưa nguồn nào xác định chính xác thời điểm.", "de": "Abgeleitet von 읽씹 durch das vorangestellte 안 (''nicht''). Es entstand, nachdem sich 읽씹 etabliert hatte, um eine noch kältere Form des Ignorierens zu benennen. Keine Quelle datiert es genau."}'::jsonb, '읽씹과 나란히 놓고 어느 쪽이 더 서운한지 따지는 대화에서 자주 나온다. 답장할 마음이 아예 없다는 뜻으로 읽히기 때문에 관계를 정리하는 신호로 해석되곤 한다.', '{"en": "Usually comes up next to 읽씹, in arguments over which one hurts more. Because it reads as having no intention of replying at all, people take it as a sign the relationship is being wound down.", "ja": "읽씹と並べて、どちらがより寂しいかを言い合う会話でよく出る。返す気が最初からないという意味に読まれるため、関係を整理する合図と解釈されがち。", "es": "Suele salir junto a 읽씹, discutiendo cuál duele más. Como se lee que no hay ninguna intención de responder, se toma como señal de que la relación se está cerrando.", "vi": "Thường đi kèm 읽씹 trong những cuộc tranh luận xem kiểu nào tổn thương hơn. Vì bị hiểu là không hề có ý định trả lời, người ta xem đó là dấu hiệu kết thúc mối quan hệ.", "de": "Kommt meist zusammen mit 읽씹 vor, wenn gestritten wird, was mehr wehtut. Da es so gelesen wird, als wolle man überhaupt nicht antworten, gilt es als Zeichen, dass eine Beziehung beendet wird."}'::jsonb, array['읽씹','잠수이별','손절'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Left unread on purpose"}, {"lang": "🇯🇵 JA", "text": "未読スルー"}, {"lang": "🇨🇳 ZH", "text": "未读不回"}, {"lang": "🇻🇳 VI", "text": "Không đọc không rep"}, {"lang": "🇪🇸 ES", "text": "Ni abrir el mensaje"}, {"lang": "🇩🇪 DE", "text": "Absichtlich ungelesen"}]'::jsonb, array[]::text[]),
('390', '회피형', 'Hoe-Pi-Hyeong', 'love', null, '가까워질수록 오히려 도망가는 연애 성향', '{"en": "Pulling away the closer someone gets", "ja": "近づかれるほど逃げたくなる恋愛傾向", "es": "Alejarse cuanto más se acerca el otro", "vi": "Càng thân càng muốn rút lui", "de": "Sich zurückziehen, je näher jemand kommt"}'::jsonb, '[회피형]', '[{"type": "명사", "definition": "좋아하는 마음이 있으면서도 상대가 가까이 다가오면 부담을 느껴 거리를 두는 연애 성향. 연락이 뜸해지거나, 갈등이 생기면 대화를 끊고 혼자 삭이는 식으로 나타난다. 애정이 없어서가 아니라 친밀함 자체가 불편해서 물러선다는 점이 핵심이라, 상대는 마음이 식었다고 오해하기 쉽다.", "definition_i18n": {"en": "A dating pattern where you do care but back off when the other person gets close, because the closeness itself feels like pressure. It shows up as replies thinning out, or as going silent and processing conflict alone. The key is that the retreat isn''t a lack of feeling — which is exactly why partners misread it as losing interest.", "ja": "好きな気持ちはあるのに、相手が近づくと負担を感じて距離を取る恋愛傾向。連絡が減ったり、対立が起きると会話を打ち切って一人で抱え込む形で表れる。愛情がないのではなく親密さ自体が苦しくて引く点が肝で、相手は気持ちが冷めたと誤解しやすい。", "es": "Patrón amoroso en el que sí quieres a la otra persona pero te retiras cuando se acerca, porque la cercanía misma pesa. Se nota en mensajes que se espacian o en callarse y digerir los conflictos a solas. La clave es que la retirada no es falta de sentimiento, y justo por eso la pareja lo lee como desinterés.", "vi": "Kiểu yêu mà bạn thật sự có tình cảm nhưng lại lùi lại khi đối phương tiến đến, vì chính sự thân mật gây áp lực. Biểu hiện là nhắn tin thưa dần, hoặc im lặng và tự xử lý mâu thuẫn một mình. Điểm mấu chốt là rút lui không phải vì hết yêu — và đó chính là lý do người kia hiểu nhầm.", "de": "Ein Beziehungsmuster, bei dem man durchaus fühlt, sich aber zurückzieht, sobald der andere näher kommt, weil die Nähe selbst Druck erzeugt. Es zeigt sich in ausdünnenden Nachrichten oder darin, bei Konflikten zu verstummen und alles allein zu verarbeiten. Entscheidend: Der Rückzug ist kein Mangel an Gefühl — genau deshalb wird er als Desinteresse missverstanden."}, "examples": [{"kor": "걔 회피형이라 싸우면 말을 아예 안 해.", "eng": "They''re the avoidant type, so when we fight they just go silent.", "ja": "あの子は回避型だから、けんかすると全然話さなくなる。", "es": "Es del tipo evitativo, así que cuando discutimos se calla del todo.", "vi": "Nó kiểu né tránh nên hễ cãi nhau là im bặt.", "de": "Er ist der vermeidende Typ — bei Streit sagt er einfach gar nichts."}]}]'::jsonb, '심리학의 성인 애착 이론(회피형·불안형·안정형)에서 온 말이다. 원래 학술 용어인데 2020년대 들어 ''애착유형 테스트''가 SNS에서 유행하면서 MBTI처럼 연애 대화의 일상어가 됐다. 심리 검사 결과를 스스로 말하는 방식으로 퍼져, 진단이라기보다 자기소개에 가깝게 쓰인다.', '{"en": "From adult attachment theory in psychology, which sorts people into avoidant, anxious and secure. It was academic vocabulary until attachment-style quizzes spread on social media in the 2020s, turning it into everyday dating talk much like MBTI. People announce their own result, so it works less as a diagnosis than as a self-introduction.", "ja": "心理学の成人愛着理論(回避型・不安型・安定型)から来た語。元は学術用語だが、2020年代に「愛着タイプ診断」がSNSで流行し、MBTIのように恋愛会話の日常語になった。診断結果を自分で言う形で広まり、診断というより自己紹介に近い使われ方をする。", "es": "Viene de la teoría del apego adulto en psicología, que distingue evitativo, ansioso y seguro. Era vocabulario académico hasta que los tests de apego se difundieron en redes en los 2020 y pasó a ser charla cotidiana de pareja, como el MBTI. Cada cual anuncia su resultado, así que funciona menos como diagnóstico y más como presentación.", "vi": "Bắt nguồn từ thuyết gắn bó ở người lớn trong tâm lý học, chia thành né tránh, lo âu và an toàn. Vốn là thuật ngữ học thuật cho tới khi trắc nghiệm kiểu gắn bó lan trên mạng xã hội thập niên 2020, biến nó thành chuyện trò yêu đương thường ngày như MBTI. Người ta tự công bố kết quả nên nó giống lời tự giới thiệu hơn là chẩn đoán.", "de": "Aus der Bindungstheorie für Erwachsene in der Psychologie, die vermeidend, ängstlich und sicher unterscheidet. Es war Fachvokabular, bis in den 2020ern Bindungstyp-Tests über Social Media liefen und daraus Alltagssprache in Beziehungsgesprächen wurde, ähnlich wie MBTI. Man verkündet sein eigenes Ergebnis, es wirkt also weniger als Diagnose denn als Selbstvorstellung."}'::jsonb, '''나 회피형이야''처럼 자기 성향을 미리 밝히거나, 상대의 행동을 설명할 때 쓴다. 성격을 규정하는 말이라 상대에게 단정적으로 붙이면 비난처럼 들릴 수 있다.', '{"en": "Said to flag your own tendency in advance (''나 회피형이야'') or to explain a partner''s behaviour. It labels a personality, so pinning it on someone flatly can come across as an accusation.", "ja": "「私は回避型」と自分の傾向を先に明かしたり、相手の行動を説明するときに使う。性格を規定する言葉なので、相手に断定的に貼ると非難に聞こえかねない。", "es": "Se usa para avisar de la propia tendencia (''나 회피형이야'') o para explicar la conducta del otro. Etiqueta una personalidad, así que soltárselo a alguien tal cual puede sonar a reproche.", "vi": "Dùng để báo trước xu hướng của mình (''나 회피형이야'') hoặc để giải thích hành vi của người kia. Đây là nhãn tính cách nên gán thẳng cho ai đó dễ nghe như lời trách.", "de": "Man kündigt damit die eigene Tendenz an (''나 회피형이야'') oder erklärt das Verhalten des Partners. Es etikettiert eine Persönlichkeit — jemandem pauschal angeheftet klingt es schnell wie ein Vorwurf."}'::jsonb, array['불안형','안정형','잠수이별'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Avoidant attachment type"}, {"lang": "🇯🇵 JA", "text": "回避型愛着"}, {"lang": "🇨🇳 ZH", "text": "回避型依恋"}, {"lang": "🇻🇳 VI", "text": "Kiểu gắn bó né tránh"}, {"lang": "🇪🇸 ES", "text": "Apego evitativo"}, {"lang": "🇩🇪 DE", "text": "Vermeidender Bindungstyp"}]'::jsonb, array[]::text[]),
('391', '불안형', 'Bul-An-Hyeong', 'love', null, '사랑받고 있는지 계속 확인하고 싶은 연애 성향', '{"en": "Needing constant reassurance that you''re loved", "ja": "愛されているか確かめ続けたくなる恋愛傾向", "es": "Necesitar comprobar sin parar que te quieren", "vi": "Luôn cần được trấn an rằng mình được yêu", "de": "Ständig Bestätigung brauchen, geliebt zu werden"}'::jsonb, '[부란형]', '[{"type": "명사", "definition": "상대의 마음이 식지 않았는지 자꾸 확인하고 싶어지는 연애 성향. 답장이 늦으면 최악을 상상하고, 표현을 자주 요구하며, 버려질까 봐 먼저 매달리는 식으로 나타난다. 회피형과 만나면 한쪽은 다가가고 한쪽은 물러서는 악순환이 생겨 자주 짝으로 언급된다.", "definition_i18n": {"en": "A dating pattern of needing to keep checking that the other person''s feelings haven''t cooled. It shows up as imagining the worst when a reply is late, asking for reassurance often, and clinging first out of fear of being left. Paired with an avoidant partner it creates the chase-and-retreat loop, which is why the two are usually named together.", "ja": "相手の気持ちが冷めていないか何度も確かめたくなる恋愛傾向。返信が遅いと最悪を想像し、愛情表現を頻繁に求め、捨てられるのが怖くて先にすがる形で表れる。回避型と組むと追う側と引く側の悪循環が生まれるため、二つはよく対で語られる。", "es": "Patrón amoroso de necesitar confirmar una y otra vez que el otro no se ha enfriado. Se nota en imaginar lo peor cuando tarda en contestar, pedir muestras de cariño a menudo y aferrarse primero por miedo al abandono. Con una pareja evitativa se forma el bucle de perseguir y retirarse, y por eso suelen nombrarse juntos.", "vi": "Kiểu yêu luôn muốn kiểm chứng rằng đối phương chưa nguội. Biểu hiện là nghĩ đến điều tệ nhất khi bị rep chậm, hay đòi hỏi thể hiện tình cảm, và bám víu trước vì sợ bị bỏ. Gặp người né tránh sẽ tạo vòng lặp đuổi - lùi, nên hai kiểu này hay được nhắc cùng nhau.", "de": "Ein Beziehungsmuster, in dem man immer wieder prüfen muss, ob die Gefühle des anderen noch da sind. Es zeigt sich darin, bei später Antwort das Schlimmste anzunehmen, oft Bestätigung einzufordern und aus Verlustangst zuerst zu klammern. Mit einem vermeidenden Gegenüber entsteht die Jagen-und-Fliehen-Schleife — deshalb werden beide meist zusammen genannt."}, "examples": [{"kor": "나 불안형이라 답장 늦으면 별생각이 다 들어.", "eng": "I''m the anxious type, so a late reply sends my head everywhere.", "ja": "私は不安型だから、返信が遅いといろいろ考えちゃう。", "es": "Soy del tipo ansioso: si tarda en contestar, me monto mil películas.", "vi": "Tao kiểu lo âu nên bị rep chậm là nghĩ đủ thứ.", "de": "Ich bin der ängstliche Typ — bei später Antwort denke ich mir alles Mögliche."}]}]'::jsonb, '심리학의 성인 애착 이론(회피형·불안형·안정형)에서 온 말이다. 원래 학술 용어인데 2020년대 들어 ''애착유형 테스트''가 SNS에서 유행하면서 MBTI처럼 연애 대화의 일상어가 됐다. 심리 검사 결과를 스스로 말하는 방식으로 퍼져, 진단이라기보다 자기소개에 가깝게 쓰인다.', '{"en": "From adult attachment theory in psychology, which sorts people into avoidant, anxious and secure. It was academic vocabulary until attachment-style quizzes spread on social media in the 2020s, turning it into everyday dating talk much like MBTI. People announce their own result, so it works less as a diagnosis than as a self-introduction.", "ja": "心理学の成人愛着理論(回避型・不安型・安定型)から来た語。元は学術用語だが、2020年代に「愛着タイプ診断」がSNSで流行し、MBTIのように恋愛会話の日常語になった。診断結果を自分で言う形で広まり、診断というより自己紹介に近い使われ方をする。", "es": "Viene de la teoría del apego adulto en psicología, que distingue evitativo, ansioso y seguro. Era vocabulario académico hasta que los tests de apego se difundieron en redes en los 2020 y pasó a ser charla cotidiana de pareja, como el MBTI. Cada cual anuncia su resultado, así que funciona menos como diagnóstico y más como presentación.", "vi": "Bắt nguồn từ thuyết gắn bó ở người lớn trong tâm lý học, chia thành né tránh, lo âu và an toàn. Vốn là thuật ngữ học thuật cho tới khi trắc nghiệm kiểu gắn bó lan trên mạng xã hội thập niên 2020, biến nó thành chuyện trò yêu đương thường ngày như MBTI. Người ta tự công bố kết quả nên nó giống lời tự giới thiệu hơn là chẩn đoán.", "de": "Aus der Bindungstheorie für Erwachsene in der Psychologie, die vermeidend, ängstlich und sicher unterscheidet. Es war Fachvokabular, bis in den 2020ern Bindungstyp-Tests über Social Media liefen und daraus Alltagssprache in Beziehungsgesprächen wurde, ähnlich wie MBTI. Man verkündet sein eigenes Ergebnis, es wirkt also weniger als Diagnose denn als Selbstvorstellung."}'::jsonb, '자기 불안을 미리 설명하며 양해를 구하는 맥락에서 많이 쓴다. 회피형과 한 세트로 언급되는 일이 많아, 둘 중 하나만 알면 대화가 잘 이어지지 않는다.', '{"en": "Mostly used to explain your own anxiety in advance and ask for some patience. It comes up paired with 회피형 so often that knowing only one of the two makes the conversation hard to follow.", "ja": "自分の不安をあらかじめ説明して理解を求める文脈で多く使う。回避型と一組で語られることが多く、片方だけ知っていても会話がつながりにくい。", "es": "Se usa sobre todo para explicar de antemano la propia ansiedad y pedir algo de paciencia. Aparece tan a menudo junto a 회피형 que conocer solo uno deja la conversación coja.", "vi": "Chủ yếu dùng để giải thích trước sự bất an của mình và xin thông cảm. Hay được nhắc cùng 회피형 tới mức chỉ biết một trong hai thì khó theo kịp câu chuyện.", "de": "Meist, um die eigene Unsicherheit vorab zu erklären und um Nachsicht zu bitten. Es fällt so oft zusammen mit 회피형, dass man dem Gespräch kaum folgen kann, wenn man nur eines der beiden kennt."}'::jsonb, array['회피형','안정형','금사빠'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Anxious attachment type"}, {"lang": "🇯🇵 JA", "text": "不安型愛着"}, {"lang": "🇨🇳 ZH", "text": "焦虑型依恋"}, {"lang": "🇻🇳 VI", "text": "Kiểu gắn bó lo âu"}, {"lang": "🇪🇸 ES", "text": "Apego ansioso"}, {"lang": "🇩🇪 DE", "text": "Ängstlicher Bindungstyp"}]'::jsonb, array[]::text[]),
('392', '안정형', 'An-Jeong-Hyeong', 'love', null, '불안해하지도 도망가지도 않는 연애 성향', '{"en": "Neither anxious nor avoidant in relationships", "ja": "不安がりも逃げもしない恋愛傾向", "es": "Ni ansioso ni evitativo en pareja", "vi": "Không lo âu cũng không né tránh", "de": "Weder ängstlich noch vermeidend in Beziehungen"}'::jsonb, '[안정형]', '[{"type": "명사", "definition": "가까워지는 것을 편하게 받아들이고, 갈등이 생겨도 도망가거나 매달리지 않고 말로 푸는 연애 성향. 애착유형 셋 중 가장 이상적인 쪽으로 이야기되며, ''안정형 만나고 싶다''는 말이 관용구처럼 쓰인다. 감정이 없어 무던한 것이 아니라 불안을 대화로 처리한다는 점이 핵심이다.", "definition_i18n": {"en": "A dating pattern that takes closeness comfortably and handles conflict by talking rather than fleeing or clinging. It''s described as the healthiest of the three attachment styles, and ''안정형 만나고 싶다'' — ''I want to date a secure type'' — has become a set phrase. The point isn''t being unbothered; it''s processing worry through conversation.", "ja": "近づくことを楽に受け入れ、対立が起きても逃げたりすがったりせず話し合いで解く恋愛傾向。愛着タイプ三つの中で最も理想的とされ、「안정형に会いたい」は決まり文句のように使われる。感情が薄くて平気なのではなく、不安を会話で処理する点が肝。", "es": "Patrón amoroso que acepta la cercanía con naturalidad y resuelve los conflictos hablando, sin huir ni aferrarse. Se describe como el más sano de los tres estilos de apego, y ''안정형 만나고 싶다'' (''quiero salir con alguien seguro'') funciona ya como frase hecha. No se trata de que no le afecte nada, sino de tramitar la inquietud hablando.", "vi": "Kiểu yêu đón nhận sự gần gũi một cách thoải mái, gặp mâu thuẫn thì nói ra chứ không bỏ chạy hay bám víu. Được mô tả là lành mạnh nhất trong ba kiểu gắn bó, và ''안정형 만나고 싶다'' (''muốn yêu người kiểu an toàn'') đã thành câu cửa miệng. Không phải vô cảm nên bình thản, mà là xử lý lo lắng bằng đối thoại.", "de": "Ein Beziehungsmuster, das Nähe gelassen annimmt und Konflikte im Gespräch löst, statt zu fliehen oder zu klammern. Es gilt als der gesündeste der drei Bindungsstile, und ''안정형 만나고 싶다'' — ''ich will jemanden mit sicherer Bindung'' — ist zur festen Wendung geworden. Es geht nicht um Gleichgültigkeit, sondern darum, Sorgen im Gespräch zu verarbeiten."}, "examples": [{"kor": "이번엔 진짜 안정형 만나고 싶다.", "eng": "This time I really want to date someone secure.", "ja": "今度こそ本当に安定型の人と付き合いたい。", "es": "Esta vez quiero de verdad a alguien con apego seguro.", "vi": "Lần này tao thật sự muốn yêu người kiểu an toàn.", "de": "Diesmal will ich wirklich jemanden mit sicherer Bindung."}]}]'::jsonb, '심리학의 성인 애착 이론(회피형·불안형·안정형)에서 온 말이다. 원래 학술 용어인데 2020년대 들어 ''애착유형 테스트''가 SNS에서 유행하면서 MBTI처럼 연애 대화의 일상어가 됐다. 심리 검사 결과를 스스로 말하는 방식으로 퍼져, 진단이라기보다 자기소개에 가깝게 쓰인다.', '{"en": "From adult attachment theory in psychology, which sorts people into avoidant, anxious and secure. It was academic vocabulary until attachment-style quizzes spread on social media in the 2020s, turning it into everyday dating talk much like MBTI. People announce their own result, so it works less as a diagnosis than as a self-introduction.", "ja": "心理学の成人愛着理論(回避型・不安型・安定型)から来た語。元は学術用語だが、2020年代に「愛着タイプ診断」がSNSで流行し、MBTIのように恋愛会話の日常語になった。診断結果を自分で言う形で広まり、診断というより自己紹介に近い使われ方をする。", "es": "Viene de la teoría del apego adulto en psicología, que distingue evitativo, ansioso y seguro. Era vocabulario académico hasta que los tests de apego se difundieron en redes en los 2020 y pasó a ser charla cotidiana de pareja, como el MBTI. Cada cual anuncia su resultado, así que funciona menos como diagnóstico y más como presentación.", "vi": "Bắt nguồn từ thuyết gắn bó ở người lớn trong tâm lý học, chia thành né tránh, lo âu và an toàn. Vốn là thuật ngữ học thuật cho tới khi trắc nghiệm kiểu gắn bó lan trên mạng xã hội thập niên 2020, biến nó thành chuyện trò yêu đương thường ngày như MBTI. Người ta tự công bố kết quả nên nó giống lời tự giới thiệu hơn là chẩn đoán.", "de": "Aus der Bindungstheorie für Erwachsene in der Psychologie, die vermeidend, ängstlich und sicher unterscheidet. Es war Fachvokabular, bis in den 2020ern Bindungstyp-Tests über Social Media liefen und daraus Alltagssprache in Beziehungsgesprächen wurde, ähnlich wie MBTI. Man verkündet sein eigenes Ergebnis, es wirkt also weniger als Diagnose denn als Selbstvorstellung."}'::jsonb, '대개 바라는 상대를 말할 때 쓰고, 자기를 안정형이라 소개하는 경우는 상대적으로 드물다. 셋 중 기준점 역할을 해서 회피형·불안형을 설명할 때 함께 나온다.', '{"en": "Usually said about the partner you want; people describe themselves as 안정형 comparatively rarely. It serves as the reference point of the three, so it comes up whenever 회피형 or 불안형 is being explained.", "ja": "たいてい望む相手について言うときに使い、自分を安定型だと紹介する例は比較的少ない。三つの中で基準点の役割をするため、回避型・不安型を説明するときに一緒に出てくる。", "es": "Suele decirse de la pareja que uno querría; describirse a uno mismo como 안정형 es comparativamente raro. Hace de punto de referencia de los tres, así que sale siempre que se explica 회피형 o 불안형.", "vi": "Thường nói về người mình muốn yêu; tự nhận mình là 안정형 thì tương đối hiếm. Nó đóng vai trò mốc chuẩn trong ba kiểu nên luôn xuất hiện khi giải thích 회피형 hay 불안형.", "de": "Meist über den gewünschten Partner gesagt; sich selbst als 안정형 zu bezeichnen ist vergleichsweise selten. Es dient als Bezugspunkt der drei und taucht deshalb immer auf, wenn 회피형 oder 불안형 erklärt wird."}'::jsonb, array['회피형','불안형','케미'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Secure attachment type"}, {"lang": "🇯🇵 JA", "text": "安定型愛着"}, {"lang": "🇨🇳 ZH", "text": "安全型依恋"}, {"lang": "🇻🇳 VI", "text": "Kiểu gắn bó an toàn"}, {"lang": "🇪🇸 ES", "text": "Apego seguro"}, {"lang": "🇩🇪 DE", "text": "Sicherer Bindungstyp"}]'::jsonb, array[]::text[]),
('393', '초식남', 'Cho-Sik-Nam', 'love', null, '연애에 소극적이고 자기 취미가 우선인 남자', '{"en": "A man who''d rather pursue his hobbies than date", "ja": "恋愛に消極的で自分の趣味が優先の男性", "es": "Un hombre que prioriza sus aficiones sobre el ligue", "vi": "Chàng trai thờ ơ chuyện yêu, ưu tiên sở thích", "de": "Ein Mann, dem Hobbys wichtiger sind als Dating"}'::jsonb, '[초싱남]', '[{"type": "명사", "definition": "연애나 이성에게 적극적으로 다가가는 데 관심이 적고, 자기 취미와 생활에 더 마음을 쏟는 남자. ''남자다움''을 앞세우지 않고 다정하지만 개인주의적인 성향으로 설명된다. 초원에서 풀을 뜯는 초식동물에 빗댄 말로, 반대쪽은 ''육식남''이다.", "definition_i18n": {"en": "A man with little interest in chasing romance, who puts his hobbies and his own routine first. He''s described as gentle rather than assertively masculine, and fairly individualist. The image is a grazing herbivore; the opposite is 육식남.", "ja": "恋愛や異性に積極的に近づくことへの関心が薄く、自分の趣味や生活に心を注ぐ男性。「男らしさ」を前面に出さず、優しいが個人主義的な性向として説明される。草を食む草食動物に例えた語で、対になるのは「육식남」。", "es": "Un hombre con poco interés en lanzarse al ligue, que antepone sus aficiones y su rutina. Se le describe como amable más que como masculino en plan asertivo, y bastante individualista. La imagen es la de un herbívoro paciendo; el opuesto es 육식남.", "vi": "Chàng trai ít hứng thú với việc chủ động theo đuổi, đặt sở thích và nếp sống riêng lên trước. Được mô tả là dịu dàng chứ không phô nam tính, và khá cá nhân chủ nghĩa. Hình ảnh là con thú ăn cỏ đang gặm cỏ; từ đối lại là 육식남.", "de": "Ein Mann mit wenig Interesse daran, aktiv zu werben, dem Hobbys und der eigene Alltag wichtiger sind. Er gilt als sanft statt betont männlich und eher individualistisch. Das Bild ist ein grasender Pflanzenfresser; das Gegenstück ist 육식남."}, "examples": [{"kor": "쟤는 완전 초식남이라 먼저 연락하는 법이 없어.", "eng": "He''s a total herbivore type — he never texts first.", "ja": "あの子は完全に草食男子だから、自分から連絡することがない。", "es": "Es totalmente del tipo herbívoro: nunca escribe primero.", "vi": "Nó đúng kiểu ''ăn cỏ'', chẳng bao giờ nhắn trước.", "de": "Er ist total der Pflanzenfresser-Typ — schreibt nie zuerst."}]}]'::jsonb, '일본에서 만들어진 ''초식계 남자(草食系男子)''가 한국으로 넘어와 줄어든 말이다. 2000년대 후반 일본 언론과 출판을 통해 개념이 퍼졌고, 한국에서는 시사IN 등 언론이 세대 현상으로 다루며 자리 잡았다. 한국판 유사어로 ''토이남''이 있었으나 초식남만큼 정착하지는 않았다.', '{"en": "A shortening of Japanese 草食系男子, ''herbivore-type man'', imported into Korean. The concept spread through Japanese press and publishing in the late 2000s, and Korean outlets such as SisaIN took it up as a generational phenomenon. A local equivalent, 토이남, was coined but never caught on as widely.", "ja": "日本で生まれた「草食系男子」が韓国に渡って縮まった語。2000年代後半に日本のメディアと出版を通じて概念が広まり、韓国では時事INなどが世代現象として扱い定着した。韓国版の類語に「토이남」があったが、草食男ほどは定着しなかった。", "es": "Acortamiento del japonés 草食系男子, ''hombre herbívoro'', importado al coreano. El concepto se difundió por la prensa y la edición japonesas a finales de los 2000, y medios coreanos como SisaIN lo trataron como fenómeno generacional. Hubo un equivalente local, 토이남, que no cuajó tanto.", "vi": "Rút gọn từ 草食系男子 (''đàn ông ăn cỏ'') của Nhật, du nhập vào tiếng Hàn. Khái niệm lan qua báo chí và xuất bản Nhật cuối thập niên 2000, rồi các báo Hàn như SisaIN bàn như một hiện tượng thế hệ. Có từ tương đương nội địa là 토이남 nhưng không phổ biến bằng.", "de": "Verkürzung des japanischen 草食系男子, ''pflanzenfressender Mann'', ins Koreanische übernommen. Das Konzept verbreitete sich Ende der 2000er über japanische Presse und Verlage; koreanische Medien wie SisaIN griffen es als Generationenphänomen auf. Ein einheimisches Pendant, 토이남, setzte sich nie so durch."}'::jsonb, '비난이라기보다 성향을 설명하는 말로 쓰지만, ''남자가 적극적이어야 한다''는 전제를 깔고 있어 듣는 사람에 따라 무시로 느낄 수 있다.', '{"en": "Used to describe a disposition rather than to criticise, though it rests on the assumption that men should be the assertive ones — so depending on the listener it can land as a slight.", "ja": "非難というより性向を説明する語として使うが、「男は積極的であるべき」という前提が敷かれているため、聞く人によっては見下しに感じられうる。", "es": "Se usa para describir un carácter más que para criticar, aunque parte de la idea de que el hombre debe llevar la iniciativa; según quién lo escuche, puede sonar despectivo.", "vi": "Dùng để mô tả tính cách hơn là chê bai, nhưng ngầm giả định ''đàn ông phải chủ động'', nên tùy người nghe có thể thấy bị coi thường.", "de": "Beschreibt eher eine Veranlagung als eine Kritik, setzt aber voraus, dass Männer die Aktiven sein sollten — je nach Zuhörer kann es also abwertend wirken."}'::jsonb, array['육식남','뇌섹남','모솔'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Herbivore man (passive in love)"}, {"lang": "🇯🇵 JA", "text": "草食系男子"}, {"lang": "🇨🇳 ZH", "text": "草食男"}, {"lang": "🇻🇳 VI", "text": "Đàn ông ăn cỏ"}, {"lang": "🇪🇸 ES", "text": "Hombre herbívoro"}, {"lang": "🇩🇪 DE", "text": "Pflanzenfresser-Typ"}]'::jsonb, array[]::text[]),
('394', '육식남', 'Yuk-Sik-Nam', 'love', null, '마음에 들면 재지 않고 바로 들이대는 남자', '{"en": "A man who makes his move without hesitating", "ja": "気に入ったら迷わず攻める男性", "es": "Un hombre que se lanza sin pensárselo", "vi": "Chàng trai thích là tiến tới luôn", "de": "Ein Mann, der ohne Zögern rangeht"}'::jsonb, '[육씽남]', '[{"type": "명사", "definition": "마음에 드는 상대가 있으면 이것저것 재지 않고 적극적으로 다가가는 남자. ''초식남''의 반대말로 함께 만들어졌고, 육식동물이 사냥하듯 직진한다는 비유다. 자신감 있다는 칭찬으로도, 부담스럽다는 지적으로도 쓰인다.", "definition_i18n": {"en": "A man who, when he likes someone, goes for it without weighing the odds. It was coined as the opposite of 초식남, on the image of a carnivore hunting. It works both as praise for confidence and as a complaint about being too much.", "ja": "気になる相手がいればあれこれ考えずに積極的に近づく男性。「초식남」の対義語として一緒に作られ、肉食動物が狩るようにまっすぐ行くという比喩。自信があるという褒め言葉にも、重いという指摘にもなる。", "es": "Un hombre que, si alguien le gusta, va a por ello sin calcular. Se acuñó como opuesto de 초식남, con la imagen del carnívoro cazando. Sirve tanto de elogio a la seguridad como de queja por resultar agobiante.", "vi": "Chàng trai hễ thích ai là tiến tới, không tính toán. Được tạo ra như từ đối của 초식남, theo hình ảnh thú ăn thịt đi săn. Vừa là lời khen tự tin, vừa là lời than phiền vì quá dồn dập.", "de": "Ein Mann, der bei Interesse ohne Abwägen rangeht. Als Gegenstück zu 초식남 geprägt, nach dem Bild eines jagenden Fleischfressers. Es dient sowohl als Lob für Selbstsicherheit wie als Klage über Aufdringlichkeit."}, "examples": [{"kor": "완전 육식남이던데? 첫날에 바로 번호 물어봤대.", "eng": "Total carnivore type — apparently he asked for her number on day one.", "ja": "完全に肉食系じゃん。初日にすぐ番号聞いたって。", "es": "Es del todo carnívoro: parece que le pidió el número el primer día.", "vi": "Đúng kiểu ''ăn thịt'' luôn, nghe nói ngày đầu đã xin số rồi.", "de": "Totaler Fleischfresser-Typ — er hat gleich am ersten Tag nach der Nummer gefragt."}]}]'::jsonb, '''초식남''이 퍼진 뒤 그 반대 개념으로 만들어진 말이다. 한국 언론(시사IN, 일요신문 등)이 초식남을 다루면서 대비어로 함께 소개했다. 단독으로 먼저 생긴 말이 아니라 쌍으로 태어난 말이라, 초식남 없이 단독으로 쓰이는 일은 드물다.', '{"en": "Coined as the counter-concept once 초식남 had spread. Korean outlets such as SisaIN and Ilyo Shinmun introduced it as the contrast while covering 초식남. It was born as half of a pair rather than on its own, so it rarely appears without its opposite.", "ja": "「초식남」が広まった後、その反対概念として作られた語。韓国のメディア(時事IN、日曜新聞など)が초식남を扱う際に対比語として紹介した。単独で先に生まれた語ではなく対で生まれたため、초식남抜きで単独に使われることは少ない。", "es": "Acuñado como concepto contrario una vez difundido 초식남. Medios coreanos como SisaIN e Ilyo Shinmun lo presentaron como contraste al tratar 초식남. Nació como mitad de una pareja, no por su cuenta, así que rara vez aparece sin su opuesto.", "vi": "Được tạo ra như khái niệm đối lập sau khi 초식남 lan rộng. Các báo Hàn như SisaIN, Ilyo Shinmun giới thiệu nó như từ tương phản khi bàn về 초식남. Sinh ra như một nửa của cặp chứ không độc lập, nên hiếm khi dùng mà không có từ kia.", "de": "Als Gegenbegriff geprägt, nachdem sich 초식남 verbreitet hatte. Koreanische Medien wie SisaIN und Ilyo Shinmun führten es als Kontrast ein, während sie über 초식남 berichteten. Es entstand als Hälfte eines Paares und steht selten allein."}'::jsonb, '주로 초식남과 대비해서 쓴다. 적극성을 긍정적으로 볼 때와 부담으로 볼 때가 갈려서, 말하는 사람의 톤을 봐야 어느 쪽인지 알 수 있다.', '{"en": "Mostly used in contrast with 초식남. Whether the assertiveness is a good thing or too much depends entirely on the speaker''s tone.", "ja": "主に초식남と対比して使う。積極性を良いと見るか重いと見るかが分かれるので、話し手のトーンを見ないとどちらか分からない。", "es": "Se usa sobre todo en contraste con 초식남. Que esa iniciativa se vea bien o como agobio depende del tono de quien habla.", "vi": "Chủ yếu dùng đối lập với 초식남. Sự chủ động được xem là tốt hay quá đà tùy vào giọng điệu người nói.", "de": "Meist im Kontrast zu 초식남. Ob die Direktheit positiv oder zu viel ist, verrät nur der Ton des Sprechers."}'::jsonb, array['초식남','헌팅','작업 걸다'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Carnivore man (goes for it)"}, {"lang": "🇯🇵 JA", "text": "肉食系男子"}, {"lang": "🇨🇳 ZH", "text": "肉食男"}, {"lang": "🇻🇳 VI", "text": "Đàn ông ăn thịt"}, {"lang": "🇪🇸 ES", "text": "Hombre carnívoro"}, {"lang": "🇩🇪 DE", "text": "Fleischfresser-Typ"}]'::jsonb, array[]::text[]),
('395', '뇌섹남', 'Noe-Sek-Nam', 'love', null, '말이 통하고 머리가 좋아 매력 있는 남자', '{"en": "A man whose brains are the attractive part", "ja": "頭の良さが魅力の男性", "es": "Un hombre cuyo atractivo es la cabeza", "vi": "Chàng trai hấp dẫn nhờ trí tuệ", "de": "Ein Mann, dessen Reiz sein Kopf ist"}'::jsonb, '[뇌셍남]', '[{"type": "명사", "definition": "''뇌가 섹시한 남자''의 준말. 외모보다 지적인 대화, 재치, 아는 것이 많은 점에서 매력을 느끼게 하는 남자를 가리킨다. 학벌이 좋다는 뜻이 아니라 말이 통하고 생각이 재미있다는 쪽에 가깝다. 여성형으로 ''뇌섹녀''도 쓴다.", "definition_i18n": {"en": "Short for 뇌가 섹시한 남자, ''a man with a sexy brain'' — someone attractive for the way he thinks and talks rather than how he looks. It doesn''t mean academic credentials so much as being good company: quick, curious, interesting to talk to. The female form 뇌섹녀 exists too.", "ja": "「脳がセクシーな男」の略。外見より知的な会話や機転、知識の広さで魅力を感じさせる男性を指す。学歴が良いという意味ではなく、話が通じて発想が面白いという方に近い。女性形の「뇌섹녀」もある。", "es": "Abreviatura de 뇌가 섹시한 남자, ''hombre de cerebro sexy'': alguien atractivo por cómo piensa y conversa, más que por su físico. No alude tanto a títulos como a ser buena compañía: agudo, curioso, interesante. También existe la forma femenina 뇌섹녀.", "vi": "Viết tắt của 뇌가 섹시한 남자, ''chàng trai có bộ não quyến rũ'' — người hấp dẫn nhờ cách nghĩ và cách nói chuyện hơn là ngoại hình. Không hẳn là bằng cấp mà là hợp chuyện: nhanh trí, ham hiểu biết, nói chuyện thú vị. Dạng nữ 뇌섹녀 cũng có.", "de": "Kurz für 뇌가 섹시한 남자, ''Mann mit sexy Gehirn'' — attraktiv durch die Art zu denken und zu reden, nicht durchs Aussehen. Gemeint sind weniger Abschlüsse als gute Gesellschaft: schlagfertig, neugierig, interessant. Die weibliche Form 뇌섹녀 gibt es ebenfalls."}, "examples": [{"kor": "얼굴보다 대화가 좋더라. 완전 뇌섹남이야.", "eng": "The conversation beat the looks. He''s a proper brainy-hot type.", "ja": "顔より会話が良かった。完全に脳セク男だわ。", "es": "La conversación superaba a la cara. Es un cerebro sexy total.", "vi": "Nói chuyện còn cuốn hơn cả mặt. Đúng chuẩn ''não quyến rũ''.", "de": "Das Gespräch war besser als das Aussehen. Absoluter Brain-Typ."}]}]'::jsonb, '''뇌''와 ''섹시''를 붙인 조어로, 2014년 무렵 예능과 방송에서 ''뇌가 섹시하다''는 표현이 유행하며 굳었다. 외모 중심 미남 기준에 대한 대안으로 소개된 말이라, 등장 당시 언론이 세태 변화로 다뤘다.', '{"en": "A coinage joining 뇌 (''brain'') and ''sexy''. It hardened around 2014 as variety shows popularised the phrase ''his brain is sexy''. It was presented as an alternative to looks-first standards of male attractiveness, so the press covered its arrival as a shift in taste.", "ja": "「脳」と「セクシー」を合わせた造語で、2014年ごろバラエティで「脳がセクシー」という表現が流行して定着した。外見中心の美男基準への代案として紹介された語で、登場当時メディアは世相の変化として扱った。", "es": "Palabra formada con 뇌 (''cerebro'') y ''sexy''. Cuajó hacia 2014, cuando los programas de variedades popularizaron la frase ''tiene un cerebro sexy''. Se presentó como alternativa al canon masculino centrado en el físico, y la prensa lo trató como un cambio de gustos.", "vi": "Từ ghép giữa 뇌 (''não'') và ''sexy''. Định hình khoảng năm 2014 khi các show giải trí làm câu ''não anh ấy quyến rũ'' thành mốt. Được giới thiệu như lựa chọn thay thế cho chuẩn đẹp trai thiên về ngoại hình, nên báo chí khi đó coi là dấu hiệu đổi gu.", "de": "Eine Wortschöpfung aus 뇌 (''Gehirn'') und ''sexy''. Sie verfestigte sich um 2014, als Varieté-Shows die Wendung ''sein Gehirn ist sexy'' populär machten. Sie galt als Alternative zum rein äußerlichen Männerideal, weshalb die Presse ihr Auftauchen als Geschmackswandel behandelte."}'::jsonb, '칭찬으로 쓰는 말이라 본인 앞에서 말해도 무난하다. 다만 ''섹시''가 들어가 있어 업무 관계처럼 격식 있는 자리에서는 피하는 게 낫다.', '{"en": "It''s a compliment, so it''s fine said to someone''s face. The word ''sexy'' inside it, though, makes it a poor fit for formal or work settings.", "ja": "褒め言葉なので本人の前で言っても差し支えない。ただし「セクシー」が入っているので、仕事の場のような改まった場では避けた方がよい。", "es": "Es un elogio, así que se puede decir a la cara. Como lleva ''sexy'' dentro, conviene evitarlo en contextos formales o de trabajo.", "vi": "Là lời khen nên nói trực tiếp cũng không sao. Nhưng vì có chữ ''sexy'' nên tránh dùng ở nơi trang trọng hay chuyện công việc.", "de": "Ein Kompliment, das man auch direkt sagen kann. Wegen des enthaltenen ''sexy'' passt es aber nicht in formelle oder berufliche Situationen."}'::jsonb, array['초식남','훈남','갓벽'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Brainy-attractive man"}, {"lang": "🇯🇵 JA", "text": "脳がセクシーな男"}, {"lang": "🇨🇳 ZH", "text": "智性感男子"}, {"lang": "🇻🇳 VI", "text": "Chàng trai não quyến rũ"}, {"lang": "🇪🇸 ES", "text": "Hombre de cerebro sexy"}, {"lang": "🇩🇪 DE", "text": "Kluger Schwarm"}]'::jsonb, array[]::text[]),
('396', '연하남', 'Yeon-Ha-Nam', 'love', null, '나보다 나이가 어린 남자 애인이나 상대', '{"en": "A younger man you''re dating or interested in", "ja": "自分より年下の男性の恋人・相手", "es": "Un chico más joven con quien sales", "vi": "Bạn trai ít tuổi hơn mình", "de": "Ein jüngerer Mann als Partner"}'::jsonb, '[연하남]', '[{"type": "명사", "definition": "나보다 나이가 어린 남자, 특히 연애 상대를 가리키는 말. 한국은 나이에 따라 말투와 호칭이 달라져서 연상연하 관계가 화제가 되기 쉽고, 그래서 이 말이 자주 쓰인다. 드라마 소재로 오래 다뤄지며 ''연하남과 연애''는 하나의 장르처럼 굳었다.", "definition_i18n": {"en": "A man younger than you, especially as a romantic partner. Korean changes speech level and forms of address with age, so an older-woman-younger-man pairing is inherently noticeable — which is why the word gets so much use. Dramas have mined it for so long that ''dating a younger man'' reads almost as a genre.", "ja": "自分より年下の男性、特に恋愛相手を指す語。韓国語は年齢によって話し方や呼び方が変わるため年上年下の関係は話題になりやすく、それでこの語がよく使われる。ドラマの題材として長く扱われ、「年下男との恋愛」は一つのジャンルのように定着した。", "es": "Un hombre más joven que tú, sobre todo como pareja. El coreano cambia el registro y el tratamiento según la edad, así que una pareja de mujer mayor y hombre menor llama la atención de por sí, y de ahí que la palabra se use tanto. Las series lo han explotado tanto que ''salir con un chico más joven'' funciona casi como género.", "vi": "Người con trai ít tuổi hơn mình, nhất là trong quan hệ yêu đương. Tiếng Hàn đổi cách nói và cách xưng hô theo tuổi, nên cặp chị lớn - em nhỏ vốn đã dễ gây chú ý, vì vậy từ này rất hay dùng. Phim truyền hình khai thác lâu tới mức ''yêu trai kém tuổi'' gần như thành một thể loại.", "de": "Ein Mann, der jünger ist als man selbst, besonders als Partner. Koreanisch ändert Sprachebene und Anrede je nach Alter, weshalb eine ältere Frau mit jüngerem Mann von sich aus auffällt — daher die Häufigkeit des Wortes. Serien haben es so lange bespielt, dass ''Beziehung mit einem Jüngeren'' fast als Genre gilt."}, "examples": [{"kor": "요즘 연하남 만나는데 나이 차 별로 안 느껴져.", "eng": "I''m seeing a younger guy these days and the age gap barely registers.", "ja": "最近年下の子と付き合ってるけど、年の差はあまり感じない。", "es": "Estoy saliendo con un chico más joven y apenas noto la diferencia de edad.", "vi": "Dạo này tao hẹn hò với trai kém tuổi, chẳng thấy chênh lệch gì mấy.", "de": "Ich date gerade einen Jüngeren, und der Altersunterschied fällt kaum auf."}]}]'::jsonb, '한자 ''연하(年下)''에 ''남''을 붙인 말이다. ''연하''는 표준국어대사전에 올라 있지만 ''연하남''은 등재돼 있지 않다. 여성형 ''연상녀''와 짝으로 ''연상연하 커플''이라는 표현이 함께 쓰인다.', '{"en": "Formed from the Sino-Korean 연하 (''younger'') plus 남 (''man''). 연하 is in the standard Korean dictionary; 연하남 is not. It pairs with 연상녀 (''older woman'') in the set phrase 연상연하 커플.", "ja": "漢字語「연하(年下)」に「남(男)」を付けた語。「연하」は標準国語大辞典にあるが「연하남」は未収録。女性形「연상녀」と対で「年上年下カップル」という表現が一緒に使われる。", "es": "Formado con el sinocoreano 연하 (''menor'') más 남 (''hombre''). 연하 está en el diccionario estándar; 연하남 no. Se empareja con 연상녀 (''mujer mayor'') en la expresión 연상연하 커플.", "vi": "Ghép từ Hán-Hàn 연하 (''kém tuổi'') với 남 (''nam''). 연하 có trong từ điển chuẩn, còn 연하남 thì không. Đi cặp với 연상녀 (''chị lớn tuổi hơn'') trong cụm 연상연하 커플.", "de": "Gebildet aus dem sinokoreanischen 연하 (''jünger'') plus 남 (''Mann''). 연하 steht im Standardwörterbuch, 연하남 nicht. Es bildet mit 연상녀 (''ältere Frau'') die feste Wendung 연상연하 커플."}'::jsonb, '나이를 기준으로 상대를 소개할 때 쓴다. 나이 차가 크면 놀리는 뉘앙스가 붙기도 해서, 당사자 앞에서는 조심하는 편이 낫다.', '{"en": "Used when introducing a partner by age. With a large gap it can pick up a teasing edge, so it''s safer not to use it in front of the couple.", "ja": "年齢を基準に相手を紹介するときに使う。年の差が大きいとからかいのニュアンスが付くこともあるので、本人の前では控えた方が無難。", "es": "Se usa al presentar a la pareja por su edad. Con mucha diferencia puede tomar un tono burlón, así que mejor no soltarlo delante de ellos.", "vi": "Dùng khi giới thiệu người yêu theo tuổi. Chênh lệch lớn thì dễ mang sắc thái trêu chọc, nên tránh nói trước mặt họ.", "de": "Wird genutzt, um einen Partner über das Alter einzuführen. Bei großem Abstand bekommt es leicht einen neckenden Ton, vor den Betroffenen also besser sparsam."}'::jsonb, array['남친','썸남','품절남'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Younger boyfriend"}, {"lang": "🇯🇵 JA", "text": "年下の彼"}, {"lang": "🇨🇳 ZH", "text": "年下男友"}, {"lang": "🇻🇳 VI", "text": "Bạn trai kém tuổi"}, {"lang": "🇪🇸 ES", "text": "Chico más joven"}, {"lang": "🇩🇪 DE", "text": "Jüngerer Freund"}]'::jsonb, array[]::text[]),
('397', '투투', 'Tu-Tu', 'love', null, '사귄 지 22일째를 챙기는 기념일', '{"en": "The 22-day anniversary couples celebrate", "ja": "付き合って22日目を祝う記念日", "es": "El aniversario de los 22 días", "vi": "Kỷ niệm 22 ngày yêu nhau", "de": "Der 22-Tage-Jahrestag eines Paares"}'::jsonb, '[투투]', '[{"type": "명사", "definition": "사귀기 시작한 지 22일째 되는 날을 기념하는 것. ''투투데이''를 줄인 말로, 숫자 2가 둘 겹친다는 뜻에서 영어 two를 두 번 썼다. 주로 10대 커플이 챙기며, 사탕 22개를 준비하거나 친구들이 돈을 모아 선물해 주기도 한다. 100일보다 훨씬 이른 시점이라 관계가 짧아도 챙길 수 있다는 점이 핵심이다.", "definition_i18n": {"en": "Marking the 22nd day since a couple got together. Short for 투투데이, from English ''two'' doubled, for the two twos in 22. It''s mostly a teenage custom — 22 sweets, or friends chipping in for a gift. The point is that it comes far earlier than the 100-day mark, so even a short relationship gets something to celebrate.", "ja": "付き合い始めて22日目を祝うこと。「투투데이」の略で、22の2が二つ重なることから英語のtwoを二度使った。主に10代のカップルが祝い、キャンディを22個用意したり、友達がお金を出し合って贈ったりする。100日よりずっと早い時点なので、交際が短くても祝えるのが肝。", "es": "Celebrar el día 22 desde que la pareja empezó. Abreviatura de 투투데이, del inglés ''two'' repetido por los dos doses de 22. Es sobre todo cosa de adolescentes: 22 caramelos, o los amigos poniendo dinero para un regalo. La clave es que llega mucho antes que los 100 días, así que incluso una relación corta tiene algo que celebrar.", "vi": "Kỷ niệm ngày thứ 22 kể từ khi yêu nhau. Rút gọn của 투투데이, lấy từ ''two'' tiếng Anh lặp hai lần theo hai số 2 của 22. Chủ yếu là tục của tuổi teen: 22 viên kẹo, hoặc bạn bè góp tiền mua quà. Điểm chính là nó đến sớm hơn mốc 100 ngày nhiều, nên yêu ngắn cũng có dịp ăn mừng.", "de": "Der 22. Tag seit Beziehungsbeginn wird gefeiert. Kurz für 투투데이, vom englischen ''two'', doppelt für die beiden Zweien in 22. Vor allem ein Teenager-Brauch: 22 Bonbons, oder Freunde legen für ein Geschenk zusammen. Entscheidend ist, dass er weit vor der 100-Tage-Marke liegt, sodass auch kurze Beziehungen etwas zu feiern haben."}, "examples": [{"kor": "우리 내일 투투인데 뭐 하지?", "eng": "Tomorrow''s our 22-day mark — what should we do?", "ja": "明日で付き合って22日だけど、何しよう?", "es": "Mañana cumplimos 22 días, ¿qué hacemos?", "vi": "Mai là 22 ngày của tụi mình rồi, làm gì đây?", "de": "Morgen sind wir 22 Tage zusammen — was machen wir?"}]}]'::jsonb, '''둘''을 뜻하는 영어 two를 두 번 겹쳐 22일을 나타낸 말이다. 2000년대 10대 커플 문화에서 ''투투데이''로 퍼졌고 줄여서 ''투투''로 쓴다. 성인들 사이에서는 더 중요한 기념일이 많아 거의 챙기지 않는다고 설명된다.', '{"en": "English ''two'' doubled to stand for the 22nd day. It spread as 투투데이 in 2000s teenage couple culture and gets shortened to 투투. Adults are described as barely observing it, since bigger anniversaries crowd it out.", "ja": "「二」を意味する英語twoを二度重ねて22日を表した語。2000年代の10代カップル文化で「투투데이」として広まり、縮めて「투투」と言う。大人の間ではもっと重要な記念日が多く、ほとんど祝わないと説明される。", "es": "El inglés ''two'' repetido para el día 22. Se difundió como 투투데이 en la cultura adolescente de los 2000 y se acorta a 투투. De los adultos se dice que apenas lo celebran, porque hay aniversarios más importantes.", "vi": "Từ ''two'' tiếng Anh lặp hai lần để chỉ ngày thứ 22. Lan dưới dạng 투투데이 trong văn hóa cặp đôi tuổi teen thập niên 2000, rút gọn thành 투투. Người lớn hầu như không kỷ niệm vì đã có nhiều mốc quan trọng hơn.", "de": "Englisch ''two'' verdoppelt für den 22. Tag. Es verbreitete sich als 투투데이 in der Teenager-Paarkultur der 2000er und wird zu 투투 gekürzt. Erwachsene feiern es kaum, da wichtigere Jahrestage es verdrängen."}'::jsonb, '주로 중고등학생 커플이 쓴다. 성인이 쓰면 귀엽게 굴거나 농담하는 뉘앙스가 된다.', '{"en": "Mainly used by middle and high school couples. Coming from an adult it sounds either playful or self-consciously cute.", "ja": "主に中高生カップルが使う。大人が使うとかわいこぶるか冗談めかすニュアンスになる。", "es": "Lo usan sobre todo parejas de instituto. En boca de un adulto suena a broma o a hacerse el mono.", "vi": "Chủ yếu các cặp cấp hai, cấp ba dùng. Người lớn nói thì nghe như đùa hoặc cố tỏ ra dễ thương.", "de": "Vor allem Paare in der Schule. Von Erwachsenen klingt es scherzhaft oder betont niedlich."}'::jsonb, array['백일','썸','남친'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "22-day anniversary"}, {"lang": "🇯🇵 JA", "text": "付き合って22日記念"}, {"lang": "🇨🇳 ZH", "text": "交往22天纪念"}, {"lang": "🇻🇳 VI", "text": "Kỷ niệm 22 ngày"}, {"lang": "🇪🇸 ES", "text": "Aniversario de 22 días"}, {"lang": "🇩🇪 DE", "text": "22-Tage-Jubiläum"}]'::jsonb, array[]::text[]),
('398', '백일', 'Baek-Il', 'love', null, '사귄 지 100일째를 크게 챙기는 기념일', '{"en": "The 100-day milestone couples make a fuss of", "ja": "付き合って100日目を盛大に祝う記念日", "es": "El hito de los 100 días de pareja", "vi": "Mốc 100 ngày yêu được ăn mừng lớn", "de": "Der 100-Tage-Meilenstein eines Paares"}'::jsonb, '[배길]', '[{"type": "명사", "definition": "사귀기 시작한 지 100일째 되는 날. 한국 커플이 가장 크게 챙기는 기념일로, 선물과 케이크·사진 촬영이 따라붙고 이날을 기점으로 관계가 안정기에 들어섰다고 본다. 아기가 태어난 지 100일을 축하하는 오랜 풍습과 같은 셈법이라, 100이라는 숫자를 한 고비로 보는 감각이 연애에도 이어진 것이다.", "definition_i18n": {"en": "The 100th day since a couple got together — the anniversary Koreans make the biggest deal of, with gifts, a cake and photos, and treated as the point where the relationship has settled. It follows the same counting as the long-standing custom of celebrating a baby''s 100th day: the sense of 100 as a threshold carried over into dating.", "ja": "付き合い始めて100日目。韓国のカップルが最も盛大に祝う記念日で、プレゼントやケーキ、写真撮影が伴い、この日を境に関係が安定期に入ったと見なす。赤ん坊の生後100日を祝う古い風習と同じ数え方で、100という数を一つの節目と見る感覚が恋愛にも引き継がれた。", "es": "El día 100 desde que la pareja empezó: el aniversario que más se celebra en Corea, con regalos, tarta y fotos, y que se toma como el punto en que la relación se asienta. Sigue la misma cuenta que la vieja costumbre de celebrar los 100 días de un bebé: la idea del 100 como umbral pasó también al noviazgo.", "vi": "Ngày thứ 100 kể từ khi yêu nhau — mốc kỷ niệm người Hàn coi trọng nhất, có quà, bánh và chụp ảnh, được xem là lúc mối quan hệ đã ổn định. Cách đếm giống tục lâu đời mừng em bé tròn 100 ngày: cảm thức xem số 100 là một cột mốc đã chuyển sang cả chuyện yêu đương.", "de": "Der 100. Tag seit Beziehungsbeginn — der Jahrestag, um den in Korea am meisten Aufhebens gemacht wird, mit Geschenken, Kuchen und Fotos, und der als Punkt gilt, an dem die Beziehung gefestigt ist. Er folgt derselben Zählung wie der alte Brauch, den 100. Lebenstag eines Babys zu feiern: das Gefühl für 100 als Schwelle ging auf die Partnerschaft über."}, "examples": [{"kor": "우리 백일에 사진관 가서 커플 사진 찍기로 했어.", "eng": "For our 100 days we''re going to a studio for couple photos.", "ja": "100日記念に写真館でカップル写真を撮ることにした。", "es": "Para nuestros 100 días vamos a un estudio a hacernos fotos de pareja.", "vi": "Dịp 100 ngày tụi tao định ra tiệm chụp ảnh đôi.", "de": "Zu unseren 100 Tagen machen wir Pärchenfotos im Studio."}]}]'::jsonb, '아기의 생후 100일을 축하하는 한국의 오랜 백일 풍습에서 숫자 감각이 이어진 것으로 설명된다. 다만 연애 기념일로서의 ''백일''이 언제부터 굳었는지를 특정하는 출처는 확인되지 않았다.', '{"en": "Usually explained as carrying over the number sense from Korea''s long-standing celebration of a baby''s 100th day. When 백일 settled specifically as a dating anniversary, however, no source pins down.", "ja": "赤ん坊の生後100日を祝う韓国の古い百日の風習から数の感覚が引き継がれたと説明される。ただし恋愛記念日としての「백일」がいつ定着したかを特定する出典は確認されていない。", "es": "Suele explicarse como una prolongación del sentido numérico de la vieja celebración coreana de los 100 días del bebé. Ahora bien, cuándo se fijó 백일 como aniversario de pareja no lo precisa ninguna fuente.", "vi": "Thường được giải thích là kế thừa cảm thức con số từ tục mừng 100 ngày tuổi của trẻ sơ sinh ở Hàn. Tuy nhiên chưa nguồn nào xác định 백일 định hình thành mốc kỷ niệm yêu đương từ khi nào.", "de": "Meist erklärt als Übertragung des Zahlgefühls aus Koreas altem Brauch, den 100. Lebenstag eines Babys zu feiern. Wann sich 백일 speziell als Beziehungsjahrestag festsetzte, datiert allerdings keine Quelle."}'::jsonb, '''백일 기념'', ''백일 선물''처럼 붙여 쓴다. 날짜를 세는 앱이나 위젯을 쓰는 커플이 많아, 서로 며칠째인지 아는 것이 기본으로 통한다.', '{"en": "Used in compounds like 백일 기념 (100-day celebration) and 백일 선물 (100-day gift). Plenty of couples run a day-counting app or widget, so knowing exactly how many days it''s been is taken for granted.", "ja": "「백일 기념」「백일 선물」のように付けて使う。日数を数えるアプリやウィジェットを使うカップルが多く、何日目かを互いに知っているのが前提とされる。", "es": "Se usa en compuestos como 백일 기념 (celebración de los 100 días) y 백일 선물 (regalo de los 100 días). Muchas parejas llevan una app o un widget contador, así que saber cuántos días llevan se da por hecho.", "vi": "Dùng trong các cụm như 백일 기념 (kỷ niệm 100 ngày), 백일 선물 (quà 100 ngày). Nhiều cặp dùng app hay widget đếm ngày, nên biết chính xác đang là ngày thứ mấy là chuyện đương nhiên.", "de": "In Zusammensetzungen wie 백일 기념 (100-Tage-Feier) und 백일 선물 (100-Tage-Geschenk). Viele Paare nutzen eine Zähl-App oder ein Widget, sodass es selbstverständlich ist, den genauen Tag zu kennen."}'::jsonb, array['투투','커플룩','남친'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "100-day anniversary"}, {"lang": "🇯🇵 JA", "text": "交際100日記念"}, {"lang": "🇨🇳 ZH", "text": "交往百日纪念"}, {"lang": "🇻🇳 VI", "text": "Kỷ niệm 100 ngày"}, {"lang": "🇪🇸 ES", "text": "Aniversario de 100 días"}, {"lang": "🇩🇪 DE", "text": "100-Tage-Jubiläum"}]'::jsonb, array[]::text[]),
('399', '솔크', 'Sol-Keu', 'love', null, '연인 없이 혼자 보내는 크리스마스', '{"en": "Spending Christmas single", "ja": "恋人なしで一人で過ごすクリスマス", "es": "Pasar la Navidad sin pareja", "vi": "Giáng sinh một mình không người yêu", "de": "Weihnachten ohne Partner verbringen"}'::jsonb, '[솔크]', '[{"type": "명사", "definition": "''솔로 크리스마스''의 준말. 연인 없이 혼자 맞는 크리스마스를 뜻한다. 한국에서 크리스마스는 가족 행사보다 연인끼리 보내는 날에 가까워서, 혼자인 사람에게는 유독 눈에 띄는 날이 된다. 그래서 자조 섞인 농담으로 많이 쓰고, 커플이 보내는 크리스마스는 ''컾크''라고 부르기도 한다.", "definition_i18n": {"en": "Short for 솔로 크리스마스, ''solo Christmas'' — Christmas spent without a partner. In Korea the day reads less as a family occasion than as a couples'' night out, which makes it conspicuous if you''re on your own. It''s mostly used as self-deprecating humour; the couples'' version is sometimes called 컾크.", "ja": "「ソロクリスマス」の略。恋人なしで迎えるクリスマスのこと。韓国のクリスマスは家族行事より恋人と過ごす日に近いため、一人の人にはとりわけ目立つ日になる。それで自嘲混じりの冗談として多く使われ、カップルのクリスマスは「컾크」と呼ぶこともある。", "es": "Abreviatura de 솔로 크리스마스, ''Navidad en solitario'': la Navidad sin pareja. En Corea ese día se vive menos como fiesta familiar que como noche de parejas, lo que lo hace muy visible si estás solo. Se usa sobre todo como humor autocrítico; a la versión en pareja a veces la llaman 컾크.", "vi": "Viết tắt của 솔로 크리스마스, ''Giáng sinh một mình'' — Giáng sinh không có người yêu. Ở Hàn, ngày này thiên về buổi hẹn của các cặp đôi hơn là dịp gia đình, nên ai độc thân sẽ thấy rõ điều đó. Chủ yếu dùng để tự trào; phiên bản cặp đôi đôi khi gọi là 컾크.", "de": "Kurz für 솔로 크리스마스, ''Solo-Weihnachten'' — Weihnachten ohne Partner. In Korea gilt der Tag weniger als Familienfest denn als Paarabend, was das Alleinsein besonders auffällig macht. Meist als selbstironischer Scherz gebraucht; die Paarversion heißt manchmal 컾크."}, "examples": [{"kor": "올해도 솔크 확정이라 그냥 집에서 영화나 볼래.", "eng": "Another solo Christmas locked in, so I''ll just watch films at home.", "ja": "今年もソロクリ確定だから、家で映画でも見るわ。", "es": "Otra Navidad en solitario asegurada, así que me quedo viendo pelis en casa.", "vi": "Năm nay lại Giáng sinh một mình rồi, thôi ở nhà xem phim.", "de": "Auch dieses Jahr Solo-Weihnachten — dann schaue ich eben zu Hause Filme."}]}]'::jsonb, '''솔로''와 ''크리스마스''를 각각 한 글자씩 따 줄인 말이다. 인터넷에 남은 기록으로는 2012년 무렵 블로그에서 쓰인 예가 확인되며, 이후 잠잠하다 유튜브를 통해 다시 퍼진 것으로 설명된다. 일본에도 같은 감각의 ''クリぼっち''(크리스마스+외톨이)가 있다.', '{"en": "A clipping that takes one syllable each from 솔로 and 크리스마스. The earliest trace online is a blog use around 2012; it then went quiet before spreading again via YouTube. Japanese has an equivalent, クリぼっち, from ''Christmas'' plus ''alone''.", "ja": "「ソロ」と「クリスマス」から一文字ずつ取った略語。ネット上の記録では2012年ごろのブログでの使用例が確認され、その後下火になりYouTubeを通じて再び広まったと説明される。日本にも同じ感覚の「クリぼっち」がある。", "es": "Recorte que toma una sílaba de 솔로 y otra de 크리스마스. El rastro más antiguo en internet es un blog de hacia 2012; luego decayó y volvió a extenderse por YouTube. El japonés tiene un equivalente, クリぼっち, de ''Navidad'' más ''solo''.", "vi": "Rút gọn lấy một âm tiết từ 솔로 và một từ 크리스마스. Dấu vết sớm nhất trên mạng là một bài blog khoảng năm 2012; sau đó lắng xuống rồi lan lại nhờ YouTube. Tiếng Nhật có từ tương đương クリぼっち, ghép ''Giáng sinh'' với ''một mình''.", "de": "Eine Kürzung aus je einer Silbe von 솔로 und 크리스마스. Die früheste Online-Spur ist eine Blognutzung um 2012; danach wurde es still, bis es über YouTube erneut aufkam. Japanisch hat mit クリぼっち ein Pendant aus ''Weihnachten'' und ''allein''."}'::jsonb, '12월에만 쓰는 계절 한정 표현이다. 스스로에 대해 농담처럼 쓰는 것이 보통이고, 남에게 ''너 솔크지?''라고 하면 놀리는 말이 된다.', '{"en": "A seasonal word, used only around December. Normally you say it about yourself as a joke; aimed at someone else (''너 솔크지?'') it becomes teasing.", "ja": "12月にだけ使う季節限定の表現。普通は自分について冗談として使い、他人に「君ソロクリでしょ?」と言うとからかいになる。", "es": "Palabra estacional, solo para diciembre. Normalmente se dice de uno mismo en broma; dirigida a otro (''너 솔크지?'') se convierte en burla.", "vi": "Từ theo mùa, chỉ dùng quanh tháng 12. Thường tự nói về mình cho vui; nhắm vào người khác (''너 솔크지?'') thì thành trêu chọc.", "de": "Ein saisonales Wort, nur rund um den Dezember. Normalerweise sagt man es scherzhaft über sich selbst; an andere gerichtet (''너 솔크지?'') wird es zur Neckerei."}'::jsonb, array['모솔','못해솔로','블랙데이'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Christmas alone"}, {"lang": "🇯🇵 JA", "text": "ソロクリスマス"}, {"lang": "🇨🇳 ZH", "text": "单身圣诞"}, {"lang": "🇻🇳 VI", "text": "Giáng sinh độc thân"}, {"lang": "🇪🇸 ES", "text": "Navidad en solitario"}, {"lang": "🇩🇪 DE", "text": "Solo-Weihnachten"}]'::jsonb, array[]::text[]),
('400', '블랙데이', 'Beul-Raek-De-I', 'love', null, '4월 14일, 솔로끼리 짜장면을 먹는 날', '{"en": "April 14, when singles eat black-bean noodles together", "ja": "4月14日、独り身どうしでジャージャー麵を食べる日", "es": "El 14 de abril, cuando los solteros comen fideos negros", "vi": "Ngày 14/4, người độc thân rủ nhau ăn mì tương đen", "de": "Der 14. April, an dem Singles schwarze Nudeln essen"}'::jsonb, '[블랙떼이]', '[{"type": "명사", "definition": "4월 14일, 2월 14일 발렌타인데이와 3월 14일 화이트데이에 아무것도 받지 못한 사람들이 모여 검은색 음식인 짜장면을 먹는 날. 검은 옷을 입기도 한다. 커플의 날 두 개가 지나간 다음 달에 배치된 솔로의 날이라, 서러움을 농담으로 바꿔 함께 즐기는 성격이 강하다. 한국에만 있는 기념일이다.", "definition_i18n": {"en": "April 14, when people who received nothing on Valentine''s Day (Feb 14) or White Day (Mar 14) get together over jajangmyeon, noodles in black bean sauce. Some wear black too. Placed one month after two couples'' days, it''s a singles'' day that turns being left out into a shared joke. It exists only in Korea.", "ja": "4月14日、2月14日のバレンタインデーと3月14日のホワイトデーに何ももらえなかった人たちが集まり、黒い食べ物であるジャージャー麵を食べる日。黒い服を着ることもある。カップルの日が二つ過ぎた翌月に置かれた独り身の日で、寂しさを冗談に変えて一緒に楽しむ性格が強い。韓国だけにある記念日。", "es": "El 14 de abril, cuando quienes no recibieron nada en San Valentín (14 de febrero) ni en el White Day (14 de marzo) se juntan a comer jajangmyeon, fideos con salsa negra de soja. Algunos se visten de negro. Colocado un mes después de dos días de parejas, es un día de solteros que convierte quedarse fuera en una broma compartida. Solo existe en Corea.", "vi": "Ngày 14/4, khi những người không nhận được gì vào Valentine (14/2) hay White Day (14/3) tụ lại ăn jajangmyeon, mì sốt tương đen. Có người còn mặc đồ đen. Đặt sau hai ngày dành cho các cặp đôi đúng một tháng, đây là ngày của người độc thân, biến chuyện bị bỏ lại thành trò đùa chung. Chỉ Hàn Quốc mới có.", "de": "Der 14. April, an dem alle, die am Valentinstag (14. Februar) und am White Day (14. März) nichts bekommen haben, sich auf Jajangmyeon treffen, Nudeln in schwarzer Bohnensauce. Manche tragen dazu Schwarz. Einen Monat nach zwei Pärchentagen gelegt, ist es ein Single-Tag, der das Übriggebliebensein in einen gemeinsamen Witz verwandelt. Es gibt ihn nur in Korea."}, "examples": [{"kor": "올해 블랙데이엔 친구들이랑 짜장면 먹으러 가기로 했어.", "eng": "For Black Day this year we''re all going out for jajangmyeon.", "ja": "今年のブラックデーは友達とジャージャー麵を食べに行くことにした。", "es": "Este Black Day quedamos con los amigos a comer jajangmyeon.", "vi": "Black Day năm nay tụi tao rủ nhau đi ăn mì tương đen.", "de": "Zum Black Day gehen wir dieses Jahr mit Freunden Jajangmyeon essen."}]}]'::jsonb, '이름은 3월 14일 화이트데이에서 왔다는 설명이 유력하다. 커플의 날인 화이트의 정반대로 한 달 뒤 솔로의 날을 두면서 ''블랙''을 붙였다는 것이다. 솔로의 우울함을 검은색으로 표현했다는 설도 함께 전해진다. 외국에는 없고 한국에서만 지키는 날이다.', '{"en": "The name most likely comes from White Day on March 14: a singles'' day set one month later was given the opposite colour. A second account holds that black simply stands for the gloom of being single. The day is not observed outside Korea.", "ja": "名称は3月14日のホワイトデーから来たという説明が有力。カップルの日であるホワイトの正反対として一か月後に独り身の日を置き「ブラック」を付けたというもの。独り身の憂鬱を黒で表したという説も併せて伝わる。海外にはなく韓国だけの日。", "es": "El nombre viene con toda probabilidad del White Day del 14 de marzo: a un día de solteros situado un mes después se le puso el color contrario. Otra versión sostiene que el negro representa sin más la melancolía de estar soltero. Fuera de Corea no se celebra.", "vi": "Tên gọi nhiều khả năng đến từ White Day ngày 14/3: ngày của người độc thân đặt sau đó một tháng được gán màu đối lập. Một cách giải thích khác cho rằng màu đen đơn giản là nỗi buồn của người độc thân. Ngoài Hàn Quốc không nơi nào có ngày này.", "de": "Der Name stammt höchstwahrscheinlich vom White Day am 14. März: Einem Single-Tag einen Monat später gab man die Gegenfarbe. Eine zweite Deutung sieht in Schwarz schlicht die Schwermut des Alleinseins. Außerhalb Koreas wird der Tag nicht begangen."}'::jsonb, '자조 섞인 농담으로 쓰지만 실제로는 친구들과 모이는 날에 가깝다. 짜장면집이 이날 붐비는 것이 뉴스로 다뤄질 만큼 자리 잡았다.', '{"en": "Said with a self-deprecating edge, though in practice it''s an excuse to gather friends. Jajangmyeon restaurants get busy enough that day to make the news.", "ja": "自嘲混じりの冗談として使うが、実際には友達と集まる日に近い。この日ジャージャー麵店が混むことがニュースになるほど定着している。", "es": "Se dice con retintín autocrítico, aunque en la práctica es una excusa para juntarse con los amigos. Los restaurantes de jajangmyeon se llenan tanto ese día que sale en las noticias.", "vi": "Nói kèm chút tự trào, nhưng thực tế là dịp để tụ tập bạn bè. Quán mì tương đen đông tới mức lên cả tin tức.", "de": "Mit selbstironischem Unterton gesagt, praktisch aber ein Anlass, Freunde zu treffen. Jajangmyeon-Lokale sind an dem Tag so voll, dass es in die Nachrichten kommt."}'::jsonb, array['화이트데이','솔크','모솔'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Black Day (singles'' day)"}, {"lang": "🇯🇵 JA", "text": "ブラックデー"}, {"lang": "🇨🇳 ZH", "text": "黑色情人节"}, {"lang": "🇻🇳 VI", "text": "Ngày Black Day"}, {"lang": "🇪🇸 ES", "text": "Black Day"}, {"lang": "🇩🇪 DE", "text": "Black Day"}]'::jsonb, array[]::text[]),
('401', '화이트데이', 'Hwa-I-Teu-De-I', 'love', null, '3월 14일, 남자가 사탕을 주는 날', '{"en": "March 14, when men give sweets in return", "ja": "3月14日、男性がキャンディを贈る日", "es": "El 14 de marzo, cuando ellos regalan caramelos", "vi": "Ngày 14/3, con trai tặng kẹo đáp lễ", "de": "Der 14. März, an dem Männer Süßigkeiten schenken"}'::jsonb, '[화이트떼이]', '[{"type": "명사", "definition": "3월 14일, 2월 14일 발렌타인데이에 초콜릿을 받은 남자가 사탕으로 답례하는 날. 한국과 일본에서 지키며, 서구의 발렌타인데이와 달리 주는 쪽이 성별로 나뉘고 한 달 뒤 갚는 구조라는 점이 특징이다. 이 두 날에 아무것도 못 받은 사람들을 위한 4월 14일 ''블랙데이''까지 이어진다.", "definition_i18n": {"en": "March 14, when a man who received chocolate on Valentine''s Day returns the gesture with sweets. Observed in Korea and Japan; unlike the Western Valentine''s Day, the giving is split by gender and repaid a month later. The sequence continues into Black Day on April 14 for anyone who got nothing on either.", "ja": "3月14日、2月14日のバレンタインデーにチョコをもらった男性がキャンディでお返しをする日。韓国と日本で行われ、欧米のバレンタインと違って贈る側が性別で分かれ、一か月後に返す構造が特徴。この二日に何ももらえなかった人のための4月14日「ブラックデー」まで続く。", "es": "El 14 de marzo, cuando el hombre que recibió chocolate en San Valentín corresponde con caramelos. Se celebra en Corea y Japón; a diferencia del San Valentín occidental, el regalo se reparte por sexos y se devuelve un mes después. La secuencia sigue con el Black Day del 14 de abril para quienes no recibieron nada.", "vi": "Ngày 14/3, khi chàng trai đã nhận sô cô la hôm Valentine đáp lại bằng kẹo. Chỉ Hàn Quốc và Nhật Bản có; khác Valentine phương Tây, việc tặng quà chia theo giới và đáp lễ sau một tháng. Chuỗi này còn nối tiếp bằng Black Day ngày 14/4 cho ai chẳng nhận được gì.", "de": "Der 14. März, an dem ein Mann, der am Valentinstag Schokolade bekam, mit Süßigkeiten erwidert. In Korea und Japan begangen; anders als der westliche Valentinstag ist das Schenken nach Geschlecht aufgeteilt und wird einen Monat später erwidert. Die Reihe setzt sich am 14. April mit dem Black Day fort, für alle, die nichts bekamen."}, "examples": [{"kor": "화이트데이에 사탕 대신 꽃 받았는데 더 좋더라.", "eng": "I got flowers instead of sweets on White Day, and honestly I preferred it.", "ja": "ホワイトデーにキャンディの代わりに花をもらったけど、そっちの方が良かった。", "es": "En White Day me regalaron flores en vez de caramelos y me gustó más.", "vi": "White Day tao được tặng hoa thay vì kẹo, thấy còn thích hơn.", "de": "Zum White Day gab es Blumen statt Süßigkeiten — fand ich sogar schöner."}]}]'::jsonb, '일본에서 시작해 한국으로 넘어온 기념일로, 발렌타인데이의 답례일로 만들어졌다. 한국에서는 여기에 4월 14일 블랙데이가 더해져 2·3·4월 14일이 한 묶음으로 이어지는 구조가 생겼다. 상술이라는 비판도 오래전부터 함께 따라다닌다.', '{"en": "A day that began in Japan and came to Korea, invented as the reciprocal to Valentine''s Day. Korea then added Black Day on April 14, producing a run of three linked 14ths across February, March and April. Criticism that the whole thing is a marketing invention has followed it just as long.", "ja": "日本で始まり韓国に渡った記念日で、バレンタインデーのお返しの日として作られた。韓国ではこれに4月14日のブラックデーが加わり、2・3・4月の14日が一続きになる構造ができた。商売のための日だという批判も昔から付いて回る。", "es": "Un día nacido en Japón y llegado a Corea, inventado como la devolución de San Valentín. Corea le añadió el Black Day del 14 de abril, formando una cadena de tres días 14 entre febrero y abril. La crítica de que todo es un invento comercial lo acompaña desde hace igual de tiempo.", "vi": "Ngày lễ khởi nguồn từ Nhật rồi sang Hàn, được tạo ra như dịp đáp lễ Valentine. Hàn Quốc thêm Black Day ngày 14/4, tạo thành chuỗi ba ngày 14 nối nhau từ tháng 2 đến tháng 4. Lời chê rằng đây chỉ là chiêu thương mại cũng đi kèm từ lâu.", "de": "Ein Tag, der in Japan entstand und nach Korea kam, erfunden als Gegenstück zum Valentinstag. Korea fügte den Black Day am 14. April hinzu, sodass drei 14. von Februar bis April eine Kette bilden. Der Vorwurf, das Ganze sei eine Marketingerfindung, begleitet ihn ebenso lange."}'::jsonb, '선물을 주고받는 날이라 연인뿐 아니라 직장·학교에서 가볍게 사탕을 돌리기도 한다. 요즘은 성별로 나누는 방식이 낡았다는 반응도 있어, 그냥 같이 챙기는 커플이 늘었다.', '{"en": "Being a gift day, it also gets marked lightly at work or school with sweets passed around, not just between couples. The gendered split now strikes many as dated, so more couples simply mark both days together.", "ja": "贈り物の日なので、恋人同士だけでなく職場や学校で軽くキャンディを配ることもある。最近は性別で分ける方式が古いという反応もあり、まとめて一緒に祝うカップルが増えた。", "es": "Como es un día de regalos, también se celebra a la ligera en el trabajo o el instituto repartiendo caramelos, no solo entre parejas. El reparto por sexos les parece anticuado a muchos, así que cada vez más parejas celebran ambos días juntas.", "vi": "Là ngày tặng quà nên ngoài các cặp đôi, ở công ty hay trường học người ta cũng phát kẹo cho vui. Cách chia theo giới nay bị nhiều người thấy lỗi thời, nên ngày càng nhiều cặp gộp hai ngày làm một.", "de": "Als Geschenktag wird er auch im Job oder in der Schule leichthin mit verteilten Süßigkeiten begangen, nicht nur unter Paaren. Die Aufteilung nach Geschlecht wirkt heute auf viele altmodisch, weshalb immer mehr Paare beide Tage einfach gemeinsam feiern."}'::jsonb, array['블랙데이','빼빼로데이','백일'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "White Day (March 14)"}, {"lang": "🇯🇵 JA", "text": "ホワイトデー"}, {"lang": "🇨🇳 ZH", "text": "白色情人节"}, {"lang": "🇻🇳 VI", "text": "Ngày White Day"}, {"lang": "🇪🇸 ES", "text": "White Day"}, {"lang": "🇩🇪 DE", "text": "White Day"}]'::jsonb, array[]::text[]),
('402', '빼빼로데이', 'Ppae-Ppae-Ro-De-I', 'love', null, '11월 11일, 막대 과자를 주고받는 날', '{"en": "November 11, when people swap stick biscuits", "ja": "11月11日、棒菓子を贈り合う日", "es": "El 11 de noviembre, cuando se regalan palitos de galleta", "vi": "Ngày 11/11, người ta tặng nhau bánh que", "de": "Der 11. November, an dem man Stäbchenkekse verschenkt"}'::jsonb, '[빼뺴로데이]', '[{"type": "명사", "definition": "11월 11일, 가늘고 긴 막대 과자 ''빼빼로''를 주고받는 날. 숫자 1이 네 개 늘어선 11월 11일이 막대 과자 모양을 닮았다는 데서 나왔다. 연인 사이만의 날은 아니고 친구·직장 동료끼리도 부담 없이 돌려서, 한국의 기념일 중 가장 폭넓게 지켜지는 편이다.", "definition_i18n": {"en": "November 11, when people exchange Pepero, thin stick-shaped biscuits. The date was chosen because 11/11 lines up four 1s that look like the biscuits. It isn''t restricted to couples — friends and colleagues hand them out casually, which makes it one of the most widely observed of these Korean days.", "ja": "11月11日、細長い棒菓子「ペペロ」を贈り合う日。1が四つ並ぶ11月11日が棒菓子の形に似ていることから生まれた。恋人だけの日ではなく友達や同僚同士でも気軽に配るので、韓国の記念日の中でも最も広く行われる部類。", "es": "El 11 de noviembre, cuando se intercambian Pepero, unos palitos finos de galleta. La fecha se eligió porque el 11/11 alinea cuatro unos que parecen los palitos. No es solo para parejas: amigos y compañeros de trabajo los reparten sin más, y por eso es de los días más celebrados en Corea.", "vi": "Ngày 11/11, khi mọi người tặng nhau Pepero, loại bánh que mảnh dài. Chọn ngày này vì 11/11 xếp thành bốn số 1 trông giống chiếc bánh. Không chỉ dành cho các cặp đôi — bạn bè, đồng nghiệp cũng tặng nhau thoải mái, nên đây là một trong những ngày được hưởng ứng rộng nhất ở Hàn.", "de": "Der 11. November, an dem man Pepero verschenkt, dünne Stäbchenkekse. Das Datum wurde gewählt, weil 11.11. vier Einsen aneinanderreiht, die wie die Kekse aussehen. Er ist nicht auf Paare beschränkt — Freunde und Kollegen verteilen sie beiläufig, was ihn zu einem der am breitesten begangenen dieser koreanischen Tage macht."}, "examples": [{"kor": "빼빼로데이라고 팀원들한테 하나씩 돌렸어.", "eng": "It''s Pepero Day, so I handed one to everyone on the team.", "ja": "ペペロデーだからチームのみんなに一つずつ配った。", "es": "Como es el Pepero Day, le di uno a cada compañero del equipo.", "vi": "Hôm nay Pepero Day nên tao phát cho cả team mỗi người một hộp.", "de": "Weil Pepero Day ist, habe ich jedem im Team eine Packung gegeben."}]}]'::jsonb, '제과 회사의 마케팅에서 비롯됐다는 설명이 널리 알려져 있으나, 여학생들이 날씬해지자는 뜻으로 주고받은 데서 시작됐다는 설도 함께 전해진다. 어느 쪽이 먼저인지는 확정되지 않았다. 지금은 편의점 매출이 급증하는 날로 매년 보도될 만큼 규모가 커졌다.', '{"en": "It is widely described as originating in a confectionery company''s marketing, though another account traces it to schoolgirls exchanging the sticks with a wish to stay slim. Which came first is unsettled. The day is now large enough that the convenience-store sales spike is reported every year.", "ja": "製菓会社のマーケティングから始まったという説明が広く知られているが、女子学生が細くなろうという意味で贈り合ったのが始まりという説も併せて伝わる。どちらが先かは確定していない。今ではコンビニの売上が急増する日として毎年報道されるほど規模が大きい。", "es": "Se suele decir que nació del marketing de una empresa de galletas, aunque otra versión lo remonta a unas estudiantes que se regalaban los palitos deseando mantenerse delgadas. Cuál fue antes no está resuelto. Hoy el día es tan grande que el pico de ventas en las tiendas de conveniencia sale en las noticias cada año.", "vi": "Nhiều nguồn nói nó khởi nguồn từ chiến dịch marketing của một hãng bánh kẹo, nhưng cũng có thuyết cho rằng nữ sinh tặng nhau bánh que với mong muốn giữ dáng thon. Cái nào trước thì chưa ngã ngũ. Giờ ngày này lớn tới mức mức tăng doanh thu cửa hàng tiện lợi được đưa tin hằng năm.", "de": "Weithin wird das Marketing eines Süßwarenherstellers als Ursprung genannt, doch eine andere Version führt ihn auf Schülerinnen zurück, die sich die Stäbchen mit dem Wunsch schlank zu bleiben schenkten. Was zuerst kam, ist ungeklärt. Heute ist der Tag so groß, dass über den Umsatzsprung in Convenience-Stores jährlich berichtet wird."}'::jsonb, '연인뿐 아니라 친구·동료에게도 가볍게 준다. 부담 없는 선물이라 고백의 계기로 삼는 경우도 있지만, 대개는 인사 정도의 의미다.', '{"en": "Given casually to friends and colleagues as much as to partners. Because the gift is so low-stakes, some use it as an opening to confess feelings, but usually it means no more than a friendly gesture.", "ja": "恋人だけでなく友達や同僚にも気軽に渡す。負担のない贈り物なので告白のきっかけにする人もいるが、たいていは挨拶程度の意味。", "es": "Se da con naturalidad tanto a amigos y compañeros como a la pareja. Al ser un regalo sin compromiso, alguno lo aprovecha para declararse, pero casi siempre no pasa de un gesto simpático.", "vi": "Tặng thoải mái cho bạn bè, đồng nghiệp chứ không riêng người yêu. Vì quà nhẹ nhàng nên có người mượn dịp để tỏ tình, nhưng thường chỉ mang nghĩa xã giao.", "de": "Wird ebenso beiläufig an Freunde und Kollegen verschenkt wie an Partner. Weil das Geschenk so unverbindlich ist, nutzen es manche als Anlass für ein Geständnis, meist bedeutet es aber kaum mehr als eine nette Geste."}'::jsonb, array['화이트데이','블랙데이','백일'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Pepero Day (Nov 11)"}, {"lang": "🇯🇵 JA", "text": "ペペロデー"}, {"lang": "🇨🇳 ZH", "text": "巧克力棒节"}, {"lang": "🇻🇳 VI", "text": "Ngày Pepero"}, {"lang": "🇪🇸 ES", "text": "Día del Pepero"}, {"lang": "🇩🇪 DE", "text": "Pepero Day"}]'::jsonb, array[]::text[]),
('403', '롱디', 'Rong-Di', 'love', null, '멀리 떨어져서 하는 장거리 연애', '{"en": "A long-distance relationship", "ja": "遠く離れて続ける遠距離恋愛", "es": "Una relación a distancia", "vi": "Yêu xa", "de": "Eine Fernbeziehung"}'::jsonb, '[롱디]', '[{"type": "명사", "definition": "서로 멀리 떨어져 지내면서 이어가는 연애. 영어 long distance를 두 글자로 줄인 말이다. 유학, 해외 취업, 지방 발령처럼 물리적으로 만나기 어려운 상황에서 쓰며, 영상통화와 메신저로 관계를 유지하는 것이 전제로 깔린다.", "definition_i18n": {"en": "A relationship kept up while living far apart. A two-syllable clipping of English ''long distance''. It''s used for study abroad, an overseas job, a posting to another city — situations where meeting is hard — and assumes the relationship runs on video calls and messaging.", "ja": "遠く離れて暮らしながら続ける恋愛。英語のlong distanceを二文字に縮めた語。留学、海外就職、地方転勤など物理的に会いにくい状況で使い、ビデオ通話とメッセンジャーで関係を保つことが前提になっている。", "es": "Una relación que se mantiene viviendo lejos el uno del otro. Recorte de dos sílabas del inglés ''long distance''. Se usa para estudios en el extranjero, un trabajo fuera o un traslado a otra ciudad, y da por supuesto que la pareja se sostiene con videollamadas y mensajes.", "vi": "Mối quan hệ duy trì khi hai người ở xa nhau. Rút gọn hai âm tiết từ ''long distance'' tiếng Anh. Dùng cho các trường hợp du học, làm việc ở nước ngoài, chuyển công tác tỉnh khác, và mặc định là tình cảm được giữ bằng gọi video và nhắn tin.", "de": "Eine Beziehung, die über große Entfernung gehalten wird. Zweisilbige Kürzung des englischen ''long distance''. Gebraucht für Auslandsstudium, Job im Ausland oder Versetzung in eine andere Stadt — und setzt voraus, dass die Beziehung über Videocalls und Messenger läuft."}, "examples": [{"kor": "우리 롱디 1년 차인데 생각보다 할 만해.", "eng": "We''re one year into long distance and it''s more doable than I expected.", "ja": "遠距離1年目だけど、思ったよりやっていける。", "es": "Llevamos un año a distancia y se lleva mejor de lo que pensaba.", "vi": "Tụi tao yêu xa được một năm rồi, đỡ hơn tao tưởng.", "de": "Wir sind seit einem Jahr in einer Fernbeziehung, und es geht besser als gedacht."}]}]'::jsonb, '영어 long distance(장거리)를 줄인 콩글리시 축약어다. 매일신문의 잠깐상식 코너는 콩글리시로 오해받지만 영어에서도 long-distance relationship이라 쓰는 표현이라고 짚는다. 다만 ''롱디''라는 두 글자 축약 자체는 한국식이다.', '{"en": "A Konglish clipping of English ''long distance''. A Maeil Shinmun explainer notes that it''s often taken for pure Konglish even though English does say ''long-distance relationship'' — the two-syllable clipping 롱디 itself, however, is Korean.", "ja": "英語long distance(長距離)を縮めた韓国式の略語。毎日新聞のコラムは、韓国式英語と誤解されがちだが英語でもlong-distance relationshipと言うと指摘する。ただし「롱디」という二文字の略自体は韓国式。", "es": "Recorte konglish del inglés ''long distance''. Una columna del Maeil Shinmun señala que suele tomarse por konglish puro aunque en inglés sí existe ''long-distance relationship''; ahora bien, el recorte 롱디 en dos sílabas sí es coreano.", "vi": "Dạng rút gọn kiểu Konglish từ ''long distance'' tiếng Anh. Một bài của Maeil Shinmun lưu ý rằng nhiều người tưởng đây là Konglish thuần, dù tiếng Anh vẫn nói ''long-distance relationship''; tuy nhiên bản rút gọn hai âm tiết 롱디 thì đúng là kiểu Hàn.", "de": "Eine konglische Kürzung des englischen ''long distance''. Eine Kolumne der Maeil Shinmun merkt an, dass es oft für reines Konglisch gehalten wird, obwohl das Englische sehr wohl ''long-distance relationship'' kennt — die zweisilbige Kürzung 롱디 ist allerdings koreanisch."}'::jsonb, '''롱디 중이다'', ''롱디 커플''처럼 쓴다. 힘들다는 전제가 깔려 있어서, 이 말을 꺼내면 대개 위로나 응원이 따라온다.', '{"en": "Used as 롱디 중이다 (we''re doing long distance) or 롱디 커플. Difficulty is baked into the word, so mentioning it usually draws sympathy or encouragement.", "ja": "「롱디中だ」「롱디カップル」のように使う。大変だという前提があるので、この語を出すとたいてい慰めや応援が返ってくる。", "es": "Se usa como 롱디 중이다 (estamos a distancia) o 롱디 커플. La dificultad va implícita, así que mencionarlo suele traer ánimos o consuelo.", "vi": "Dùng như 롱디 중이다 (đang yêu xa) hay 롱디 커플. Từ này mặc định là vất vả, nên nhắc tới thường được an ủi hoặc động viên.", "de": "Als 롱디 중이다 (wir führen eine Fernbeziehung) oder 롱디 커플. Die Mühe steckt schon im Wort, deshalb folgen meist Mitgefühl oder Zuspruch."}'::jsonb, array['남친','여친','밀당'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Long-distance relationship"}, {"lang": "🇯🇵 JA", "text": "遠距離恋愛"}, {"lang": "🇨🇳 ZH", "text": "异地恋"}, {"lang": "🇻🇳 VI", "text": "Yêu xa"}, {"lang": "🇪🇸 ES", "text": "Relación a distancia"}, {"lang": "🇩🇪 DE", "text": "Fernbeziehung"}]'::jsonb, array[]::text[]),
('404', '연프', 'Yeon-Peu', 'love', null, '출연자들이 짝을 찾아가는 연애 리얼리티 프로그램', '{"en": "A dating reality show", "ja": "出演者が相手を探す恋愛リアリティ番組", "es": "Un reality de citas", "vi": "Show hẹn hò thực tế", "de": "Eine Dating-Realityshow"}'::jsonb, '[연프]', '[{"type": "명사", "definition": "''연애 프로그램''의 준말. 서로 모르는 출연자들이 정해진 기간 함께 지내며 짝을 찾아가는 과정을 담는 예능 장르를 가리킨다. 2020년대 한국에서 크게 늘어난 형식이라, 여기서 나온 말투와 표현이 실제 연애 대화에까지 옮겨 오는 일이 많다.", "definition_i18n": {"en": "Short for 연애 프로그램, ''dating programme'' — the genre in which strangers live together for a set period while pairing off. The format multiplied in Korea through the 2020s, and the phrasing that appears on these shows regularly crosses over into how people actually talk about dating.", "ja": "「恋愛番組」の略。互いに知らない出演者が一定期間一緒に過ごしながら相手を探す過程を描くバラエティのジャンルを指す。2020年代の韓国で大きく増えた形式で、ここで生まれた言い回しが実際の恋愛会話にまで移ってくることが多い。", "es": "Abreviatura de 연애 프로그램, ''programa de citas'': el género en el que desconocidos conviven un tiempo determinado mientras se emparejan. El formato se multiplicó en Corea durante los 2020, y las expresiones que salen en estos programas pasan a menudo al habla real sobre relaciones.", "vi": "Viết tắt của 연애 프로그램, ''chương trình hẹn hò'' — thể loại mà những người lạ sống chung một thời gian nhất định để tìm bạn đời. Định dạng này bùng nổ ở Hàn thập niên 2020, và cách nói xuất hiện trong show thường lan sang cả đời thật khi bàn chuyện yêu đương.", "de": "Kurz für 연애 프로그램, ''Dating-Sendung'' — das Genre, in dem Fremde eine festgelegte Zeit zusammenleben und sich verpaaren. Das Format vervielfachte sich in Korea in den 2020ern, und die Sprache dieser Shows wandert regelmäßig in echte Beziehungsgespräche."}, "examples": [{"kor": "요즘 연프 너무 많아서 뭐부터 봐야 할지 모르겠어.", "eng": "There are so many dating shows now I don''t know which to start with.", "ja": "最近恋愛番組が多すぎて、どれから見ればいいか分からない。", "es": "Hay tantos realities de citas ahora que no sé por cuál empezar.", "vi": "Dạo này show hẹn hò nhiều quá, không biết xem cái nào trước.", "de": "Es gibt inzwischen so viele Dating-Shows, dass ich nicht weiß, womit ich anfangen soll."}]}]'::jsonb, '''연애 프로그램''을 두 글자로 줄인 말이다. 언제 처음 쓰였는지 특정하는 출처는 확인되지 않았고, 2020년대 들어 이 장르가 쏟아지면서 시청자들이 편하게 줄여 부르며 굳은 것으로 보인다.', '{"en": "A two-syllable clipping of 연애 프로그램. No source pins down its first use; it appears to have hardened simply because viewers needed a short name once the genre proliferated in the 2020s.", "ja": "「연애 프로그램」を二文字に縮めた語。初出を特定する出典は確認されておらず、2020年代にこのジャンルが急増し視聴者が気軽に略して呼ぶうちに定着したと見られる。", "es": "Recorte de dos sílabas de 연애 프로그램. Ninguna fuente fija su primer uso; parece haberse asentado sin más porque los espectadores necesitaban un nombre corto cuando el género se disparó en los 2020.", "vi": "Rút gọn hai âm tiết của 연애 프로그램. Chưa nguồn nào xác định lần dùng đầu tiên; có vẻ nó định hình đơn giản vì khán giả cần một tên gọi ngắn khi thể loại này bùng nổ thập niên 2020.", "de": "Zweisilbige Kürzung von 연애 프로그램. Keine Quelle datiert die erste Verwendung; sie verfestigte sich offenbar einfach, weil Zuschauer einen kurzen Namen brauchten, als das Genre in den 2020ern explodierte."}'::jsonb, '프로그램 이야기를 할 때 쓰지만, 연애 방식이 방송 같다는 뜻으로 ''연프 찍냐''처럼 놀리듯 쓰기도 한다.', '{"en": "Used when talking about the shows, but also as teasing — ''연프 찍냐?'', ''are you filming a dating show?'' — when someone''s romance looks staged.", "ja": "番組の話をするときに使うが、恋愛の仕方が放送みたいだという意味で「恋愛番組でも撮ってるの?」とからかうようにも使う。", "es": "Se usa al hablar de los programas, pero también en broma — ''연프 찍냐?'', ''¿estás rodando un reality?'' — cuando el romance de alguien parece de guion.", "vi": "Dùng khi bàn về các show, nhưng cũng để trêu — ''연프 찍냐?'', ''quay show hẹn hò à?'' — khi chuyện tình của ai đó trông như dàn dựng.", "de": "Beim Reden über die Sendungen, aber auch neckend — ''연프 찍냐?'', ''drehst du eine Dating-Show?'' — wenn jemandes Romanze inszeniert wirkt."}'::jsonb, array['플러팅','썸','그린라이트'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Dating reality show"}, {"lang": "🇯🇵 JA", "text": "恋愛リアリティ番組"}, {"lang": "🇨🇳 ZH", "text": "恋爱综艺"}, {"lang": "🇻🇳 VI", "text": "Show hẹn hò"}, {"lang": "🇪🇸 ES", "text": "Reality de citas"}, {"lang": "🇩🇪 DE", "text": "Dating-Realityshow"}]'::jsonb, array[]::text[]),
('405', '럽스타그램', 'Reop-Seu-Ta-Geu-Raem', 'love', null, 'SNS에 커플 사진을 올려 애정을 드러내는 것', '{"en": "Posting couple photos to show off a relationship", "ja": "SNSにカップル写真を上げて愛情を見せること", "es": "Subir fotos de pareja a redes para presumir", "vi": "Đăng ảnh đôi lên mạng khoe tình cảm", "de": "Pärchenfotos posten, um die Beziehung zu zeigen"}'::jsonb, '[럽쓰타그램]', '[{"type": "명사", "definition": "''러브(love)''와 ''인스타그램''을 합친 말. 연인이 SNS에 서로의 사진이나 데이트 모습을 올려 사귀는 사이임을 드러내는 것을 뜻한다. 기념일 사진, 함께 간 여행지, 선물 인증 같은 게시물이 대표적이다. 요즘은 대놓고 드러내기보다 은근히 티 내는 쪽을 선호하는 분위기가 생겨, 럽스타그램을 하는 사람이 줄었다는 이야기도 나온다.", "definition_i18n": {"en": "A blend of ''love'' and ''Instagram'': posting photos of your partner or your dates so everyone can see you''re together. Anniversary pictures, trips taken together, a gift held up to the camera. The mood has shifted lately towards hinting rather than announcing, and people say fewer are doing it now.", "ja": "「ラブ(love)」と「インスタグラム」を合わせた語。恋人がSNSに互いの写真やデートの様子を上げて交際中だと示すこと。記念日の写真、一緒に行った旅行先、プレゼントの証拠写真などが代表的。最近は大っぴらに見せるより、それとなく匂わせる方を好む空気が生まれ、럽스타그램をする人が減ったとも言われる。", "es": "Mezcla de ''love'' e ''Instagram'': subir fotos de tu pareja o de vuestras citas para que se vea que estáis juntos. Fotos de aniversario, viajes compartidos, el regalo enseñado a cámara. Últimamente se prefiere insinuar antes que anunciar, y se dice que ya lo hace menos gente.", "vi": "Ghép ''love'' với ''Instagram'': đăng ảnh người yêu hay ảnh hẹn hò để ai cũng thấy hai người đang yêu. Điển hình là ảnh kỷ niệm, chuyến đi chung, món quà giơ lên chụp. Gần đây xu hướng chuyển sang ám chỉ nhẹ thay vì công khai, và người ta nói số người làm việc này đã giảm.", "de": "Eine Mischung aus ''love'' und ''Instagram'': Fotos vom Partner oder von Dates posten, damit alle sehen, dass man zusammen ist. Typisch sind Jahrestagsbilder, gemeinsame Reisen, ein in die Kamera gehaltenes Geschenk. Zuletzt geht der Trend eher zum Andeuten als zum Verkünden, und es heißt, weniger Leute machten es noch."}, "examples": [{"kor": "걔 요즘 럽스타그램 엄청 하더라, 매일 올라와.", "eng": "They''ve been posting couple pics nonstop — something new every day.", "ja": "あの子最近ラブスタグラムすごいよ、毎日上がってる。", "es": "Últimamente no para de subir fotos de pareja, cada día una.", "vi": "Dạo này nó khoe ảnh đôi dữ lắm, ngày nào cũng đăng.", "de": "Er postet gerade ständig Pärchenfotos — jeden Tag was Neues."}]}]'::jsonb, '영어 love와 Instagram을 붙인 합성어다. 인스타그램에 커플 사진을 올리는 문화가 자리 잡으며 생겼고, 연예인 커플의 공개 연애를 다루는 기사에서도 관용적으로 쓰인다. 최근에는 트렌드 미디어가 ''럽스타그램은 구세대''라는 인식 변화 자체를 기사로 다룰 만큼 흐름이 바뀌었다.', '{"en": "A portmanteau of English ''love'' and ''Instagram''. It emerged as posting couple photos became normal, and Korean press uses it routinely when covering celebrities going public. Trend media now report on the shift itself — that 럽스타그램 reads as an older generation''s habit.", "ja": "英語loveとInstagramを合わせた合成語。インスタにカップル写真を上げる文化が定着する中で生まれ、芸能人の公開恋愛を扱う記事でも慣用的に使われる。最近はトレンドメディアが「ラブスタグラムは旧世代」という認識の変化自体を記事にするほど流れが変わった。", "es": "Palabra maleta de ''love'' e ''Instagram''. Surgió cuando subir fotos de pareja se volvió normal, y la prensa coreana la usa de rutina al cubrir a famosos que hacen pública su relación. Los medios de tendencias ya informan del propio cambio: que el 럽스타그램 suena a costumbre de una generación anterior.", "vi": "Từ ghép giữa ''love'' và ''Instagram''. Xuất hiện khi việc đăng ảnh đôi thành chuyện bình thường, và báo Hàn dùng thường xuyên khi đưa tin người nổi tiếng công khai. Truyền thông xu hướng nay còn viết về chính sự thay đổi này — rằng 럽스타그램 nghe như thói quen của thế hệ trước.", "de": "Ein Kofferwort aus englisch ''love'' und ''Instagram''. Es entstand, als Pärchenfotos zur Normalität wurden, und die koreanische Presse verwendet es routinemäßig, wenn Prominente ihre Beziehung öffentlich machen. Trendmedien berichten inzwischen über den Wandel selbst — dass 럽스타그램 nach der Gewohnheit einer älteren Generation klingt."}'::jsonb, '제3자를 두고 ''럽스타그램 하네''처럼 쓰는 일이 많고, 부러움과 살짝의 비아냥이 함께 섞인다. 본인이 스스로 이 말을 쓰는 경우는 드물다.', '{"en": "Usually said about someone else — ''럽스타그램 하네'' — with a mix of envy and mild snark. People rarely use it about themselves.", "ja": "第三者について「ラブスタグラムしてるね」と言うことが多く、羨ましさと軽い皮肉が混ざる。自分について使うことは少ない。", "es": "Casi siempre se dice de otra persona — ''럽스타그램 하네'' — con una mezcla de envidia y guasa. Rara vez se aplica a uno mismo.", "vi": "Thường nói về người khác — ''럽스타그램 하네'' — pha giữa ganh tị và hơi xỏ xiên. Hiếm ai tự nói về mình.", "de": "Meist über andere gesagt — ''럽스타그램 하네'' — mit einer Mischung aus Neid und leichtem Spott. Über sich selbst benutzt man es selten."}'::jsonb, array['커플룩','백일','케미'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Couple posts on Instagram"}, {"lang": "🇯🇵 JA", "text": "ラブスタグラム"}, {"lang": "🇨🇳 ZH", "text": "社交媒体秀恩爱"}, {"lang": "🇻🇳 VI", "text": "Khoe ảnh đôi trên mạng"}, {"lang": "🇪🇸 ES", "text": "Presumir de pareja en redes"}, {"lang": "🇩🇪 DE", "text": "Pärchenposts auf Instagram"}]'::jsonb, array[]::text[]),
('406', '커플룩', 'Keo-Peul-Ruk', 'love', null, '커플이 맞춰 입는 옷차림', '{"en": "Matching outfits worn by a couple", "ja": "カップルで揃えて着る服装", "es": "Ropa a juego que lleva una pareja", "vi": "Trang phục đôi mặc giống nhau", "de": "Partnerlook eines Paares"}'::jsonb, '[커플룩]', '[{"type": "명사", "definition": "연인이 같거나 비슷한 옷을 맞춰 입는 것. 영어 couple과 look을 붙인 콩글리시로, 영어권에서는 matching outfits라고 한다. 완전히 똑같이 입기보다 색이나 소재를 맞추는 식이 흔하고, 신발이나 모자만 맞추는 가벼운 방식도 있다. 사귀는 사이임을 밖으로 드러내는 표시라 기념일이나 여행 때 특히 많이 한다.", "definition_i18n": {"en": "A couple dressing alike or nearly alike. Konglish from ''couple'' plus ''look''; English says ''matching outfits''. Rather than identical clothes it''s usually a shared colour or fabric, and a lighter version matches only the shoes or caps. Since it announces a relationship in public, it peaks on anniversaries and trips.", "ja": "恋人が同じか似た服を揃えて着ること。英語のcoupleとlookを合わせた韓国式英語で、英語圏ではmatching outfitsと言う。完全にお揃いより色や素材を合わせる形が多く、靴や帽子だけ合わせる軽いやり方もある。交際中だと外に示す印なので、記念日や旅行のときに特に多い。", "es": "Una pareja vistiendo igual o casi igual. Konglish de ''couple'' más ''look''; en inglés se dice ''matching outfits''. Más que ropa idéntica suele ser un color o un tejido común, y hay una versión ligera en la que solo coinciden los zapatos o las gorras. Como declara la relación en público, se lleva sobre todo en aniversarios y viajes.", "vi": "Cặp đôi mặc giống hoặc gần giống nhau. Konglish ghép ''couple'' với ''look''; tiếng Anh nói ''matching outfits''. Thường không mặc y hệt mà đồng bộ màu hoặc chất liệu, cũng có kiểu nhẹ nhàng chỉ giống giày hay mũ. Vì là cách công khai đang yêu nên hay diện dịp kỷ niệm và đi du lịch.", "de": "Ein Paar, das gleich oder ähnlich gekleidet ist. Konglisch aus ''couple'' und ''look''; im Englischen heißt es ''matching outfits''. Statt identischer Kleidung stimmt man meist Farbe oder Stoff ab, in der leichten Variante nur Schuhe oder Mützen. Da es die Beziehung öffentlich macht, sieht man es besonders an Jahrestagen und auf Reisen."}, "examples": [{"kor": "제주도 갈 때 커플룩 맞춰 입기로 했어.", "eng": "We''ve decided to do matching outfits for the Jeju trip.", "ja": "済州島に行くときはカップルルックを合わせることにした。", "es": "Para el viaje a Jeju hemos quedado en ir a juego.", "vi": "Đi Jeju tụi tao định mặc đồ đôi.", "de": "Für die Jeju-Reise ziehen wir Partnerlook an."}]}]'::jsonb, '영어 couple과 look을 붙여 만든 콩글리시다. 영어에서 look은 이런 식으로 명사처럼 쓰이지 않는다. 표준국어대사전에는 등재돼 있지 않으며, 언제부터 쓰였는지 특정하는 출처는 확인되지 않았다.', '{"en": "Konglish formed from English ''couple'' and ''look''; English doesn''t use ''look'' as a noun this way. It is not in the standard Korean dictionary, and no source pins down when it came into use.", "ja": "英語coupleとlookを合わせて作った韓国式英語。英語ではlookをこのように名詞的には使わない。標準国語大辞典には未収録で、いつから使われたかを特定する出典は確認されていない。", "es": "Konglish formado con ''couple'' y ''look''; el inglés no usa ''look'' como sustantivo de este modo. No figura en el diccionario estándar y ninguna fuente precisa desde cuándo se usa.", "vi": "Konglish ghép ''couple'' và ''look''; tiếng Anh không dùng ''look'' như danh từ kiểu này. Không có trong từ điển chuẩn và chưa nguồn nào xác định dùng từ khi nào.", "de": "Konglisch aus ''couple'' und ''look''; im Englischen wird ''look'' so nicht als Substantiv verwendet. Es steht nicht im Standardwörterbuch, und keine Quelle datiert den Beginn der Verwendung."}'::jsonb, '''커플룩 입다'', ''커플룩 맞추다''처럼 쓴다. 티 내는 걸 부담스러워하는 사람도 있어, 하기 전에 서로 합의하는 경우가 많다.', '{"en": "Used as 커플룩 입다 (to wear one) or 커플룩 맞추다 (to coordinate one). Not everyone is comfortable being that visible, so couples usually agree on it beforehand.", "ja": "「커플룩 입다」「커플룩 맞추다」のように使う。目立つのを負担に感じる人もいるので、事前に相談してから着ることが多い。", "es": "Se usa como 커플룩 입다 (llevarlo) o 커플룩 맞추다 (coordinarlo). No a todo el mundo le gusta ser tan visible, así que suele acordarse antes.", "vi": "Dùng như 커플룩 입다 (mặc đồ đôi) hay 커플룩 맞추다 (phối đồ đôi). Không phải ai cũng thoải mái phô ra nên thường bàn trước với nhau.", "de": "Als 커플룩 입다 (tragen) oder 커플룩 맞추다 (abstimmen). Nicht alle mögen es, so sichtbar zu sein, deshalb spricht man es meist vorher ab."}'::jsonb, array['럽스타그램','백일','남친'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Matching couple outfits"}, {"lang": "🇯🇵 JA", "text": "カップルルック"}, {"lang": "🇨🇳 ZH", "text": "情侣装"}, {"lang": "🇻🇳 VI", "text": "Đồ đôi"}, {"lang": "🇪🇸 ES", "text": "Ropa a juego"}, {"lang": "🇩🇪 DE", "text": "Partnerlook"}]'::jsonb, array[]::text[]),
('407', '잠수이별', 'Jam-Su-I-Byeol', 'love', null, '말없이 연락을 끊고 사라지는 이별', '{"en": "Breaking up by vanishing without a word", "ja": "何も言わず連絡を絶って消える別れ", "es": "Romper desapareciendo sin decir nada", "vi": "Chia tay bằng cách biến mất không lời", "de": "Schlussmachen durch spurloses Verschwinden"}'::jsonb, '[잠수이별]', '[{"type": "명사", "definition": "헤어지자는 말도 없이 연락을 끊고 사라져 버리는 이별. ''잠수(潛水)''는 물속으로 숨는다는 뜻에서 연락을 끊고 잠적한다는 은어로 쓰이며, 여기에 ''이별''을 붙였다. 영어권의 고스팅(ghosting)과 같은 행동이다. 상대는 헤어졌다는 사실조차 확인받지 못한 채 남겨져서, 이별 방식 중 가장 무책임한 축으로 이야기된다.", "definition_i18n": {"en": "Ending a relationship by cutting contact and disappearing, without ever saying it''s over. 잠수 means ''diving underwater'' and is slang for going off the grid; 이별 is ''parting''. It''s the same behaviour English calls ghosting. The other person is left without even confirmation that it ended, which is why it''s talked about as the most irresponsible way to break up.", "ja": "別れようの一言もなく連絡を絶って消えてしまう別れ。「잠수(潜水)」は水に潜る意味から、連絡を絶って姿を消すという隠語として使われ、そこに「별れ」を付けた語。英語圏のゴースティングと同じ行動。相手は別れたという事実の確認すらもらえないまま残されるので、最も無責任な別れ方として語られる。", "es": "Terminar una relación cortando el contacto y desapareciendo, sin decir nunca que se acabó. 잠수 significa ''bucear'' y es jerga para esfumarse; 이별 es ''ruptura''. Es lo que en inglés se llama ghosting. A la otra persona la dejan sin siquiera la confirmación de que ha terminado, y por eso se habla de ello como la forma más irresponsable de cortar.", "vi": "Chấm dứt mối quan hệ bằng cách cắt liên lạc và biến mất, không hề nói lời chia tay. 잠수 nghĩa là ''lặn xuống nước'', tiếng lóng chỉ việc mất hút; 이별 là ''chia tay''. Chính là hành vi tiếng Anh gọi là ghosting. Người kia bị bỏ lại mà không có cả một lời xác nhận đã kết thúc, nên đây bị coi là cách chia tay vô trách nhiệm nhất.", "de": "Eine Beziehung beenden, indem man den Kontakt abbricht und verschwindet, ohne je Schluss zu machen. 잠수 heißt ''tauchen'' und ist Slang für Abtauchen; 이별 ist ''Trennung''. Es ist genau das, was im Englischen ghosting heißt. Die andere Person bleibt ohne jede Bestätigung zurück, dass es vorbei ist — deshalb gilt es als die verantwortungsloseste Art zu gehen."}, "examples": [{"kor": "세 달 만나다가 잠수이별당했어. 아직도 이유를 몰라.", "eng": "Three months in, they ghosted me. I still don''t know why.", "ja": "三か月付き合って音信不通で振られた。今も理由が分からない。", "es": "Tras tres meses me hizo ghosting. Sigo sin saber por qué.", "vi": "Yêu ba tháng rồi bị ''lặn'' mất. Tới giờ vẫn không biết lý do.", "de": "Nach drei Monaten wurde ich geghostet. Ich weiß bis heute nicht, warum."}]}]'::jsonb, '''잠수를 타다''(연락을 끊고 잠적하다)라는 기존 은어에 ''이별''을 붙여 만든 말이다. 언론에서는 서구의 ''고스팅''과 같은 현상으로 소개되며, Z세대 연애에서 흔하게 나타나는 이별 방식으로 다뤄진다. 언제 처음 쓰였는지 특정하는 출처는 확인되지 않았다.', '{"en": "Built on the existing slang 잠수를 타다, ''to go under and disappear'', with 이별 attached. Korean media introduce it as the same phenomenon as Western ghosting and treat it as a common way Gen Z relationships end. No source pins down its first use.", "ja": "「잠수를 타다」(連絡を絶って姿を消す)という既存の隠語に「別れ」を付けて作った語。メディアでは欧米の「ゴースティング」と同じ現象として紹介され、Z世代の恋愛でよくある別れ方として扱われる。初出を特定する出典は確認されていない。", "es": "Formado sobre la jerga ya existente 잠수를 타다, ''esfumarse'', añadiéndole 이별. Los medios coreanos lo presentan como el mismo fenómeno que el ghosting occidental y lo tratan como una forma habitual de terminar entre la generación Z. Ninguna fuente fija su primer uso.", "vi": "Dựng trên tiếng lóng sẵn có 잠수를 타다, ''lặn mất tăm'', rồi thêm 이별. Báo Hàn giới thiệu đây là hiện tượng giống ghosting phương Tây và xem là cách chia tay phổ biến ở Gen Z. Chưa nguồn nào xác định lần dùng đầu tiên.", "de": "Gebildet aus dem bestehenden Slang 잠수를 타다, ''abtauchen und verschwinden'', plus 이별. Koreanische Medien stellen es als dasselbe Phänomen wie westliches Ghosting vor und behandeln es als verbreitete Trennungsform der Gen Z. Keine Quelle datiert die erste Verwendung."}'::jsonb, '''잠수이별하다''(내가 하다)보다 ''잠수이별당하다''(내가 당하다) 쪽으로 훨씬 많이 쓴다. 부정적인 말이라 당사자에게 직접 쓰면 비난이 된다.', '{"en": "Far more common in the passive — 잠수이별당하다 (to be ghosted) — than the active. It''s a condemnation, so used to someone''s face it reads as an accusation.", "ja": "「잠수이별하다」(自分がする)より「잠수이별당하다」(される)の方がはるかに多く使う。否定的な語なので当人に直接使うと非難になる。", "es": "Mucho más frecuente en pasiva — 잠수이별당하다 (que te hagan ghosting) — que en activa. Es una condena, así que dicho a la cara suena a reproche.", "vi": "Dùng thể bị động — 잠수이별당하다 (bị lặn mất) — nhiều hơn hẳn thể chủ động. Là từ tiêu cực nên nói thẳng với người ta là lời buộc tội.", "de": "Weit häufiger im Passiv — 잠수이별당하다 (geghostet werden) — als im Aktiv. Es ist ein Vorwurf, direkt gesagt also eine Anklage."}'::jsonb, array['환승이별','읽씹','회피형'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Ghosting someone"}, {"lang": "🇯🇵 JA", "text": "音信不通の別れ"}, {"lang": "🇨🇳 ZH", "text": "人间蒸发式分手"}, {"lang": "🇻🇳 VI", "text": "Chia tay kiểu lặn mất"}, {"lang": "🇪🇸 ES", "text": "Ruptura por ghosting"}, {"lang": "🇩🇪 DE", "text": "Trennung durch Ghosting"}]'::jsonb, array[]::text[]),
('408', '연애세포', 'Yeon-Ae-Se-Po', 'love', null, '연애에 대한 감각을 세포에 빗댄 말', '{"en": "Your capacity for romance, imagined as cells", "ja": "恋愛の感覚を細胞にたとえた言葉", "es": "La capacidad de enamorarse, imaginada como células", "vi": "Khả năng yêu đương ví như tế bào", "de": "Die Fähigkeit zu lieben, als Zellen gedacht"}'::jsonb, '[여내세포]', '[{"type": "명사", "definition": "연애에 대한 감각이나 설렘을 비유적으로 이르는 말. 실제로 있는 세포가 아니라, 오래 연애를 쉬면 그 감각이 무뎌진다는 것을 몸속 세포가 죽는 것처럼 표현한 것이다. 그래서 ''연애세포가 죽었다'', ''연애세포가 살아났다''처럼 살고 죽는 동사와 함께 쓰는 것이 기본형이다.", "definition_i18n": {"en": "A figurative name for your feel for romance — the flutter of it. There is no such cell; the idea is that going a long time without dating dulls the instinct, described as if cells in your body had died. So it almost always appears with verbs of living and dying: 연애세포가 죽었다 (they''ve died), 연애세포가 살아났다 (they''ve come back to life).", "ja": "恋愛の感覚やときめきを比喩的に言う言葉。実在する細胞ではなく、長く恋愛を休むとその感覚が鈍ることを、体内の細胞が死ぬように表現したもの。だから「恋愛細胞が死んだ」「恋愛細胞が生き返った」のように生死の動詞と一緒に使うのが基本形。", "es": "Nombre figurado para el olfato romántico, esa chispa. No existe tal célula: la idea es que pasar mucho tiempo sin salir con nadie embota el instinto, descrito como si se te murieran células. Por eso casi siempre va con verbos de vida y muerte: 연애세포가 죽었다 (se murieron), 연애세포가 살아났다 (revivieron).", "vi": "Cách nói ví von về cảm giác yêu đương, cái rung động ấy. Không có tế bào nào như vậy; ý là lâu không yêu thì bản năng cùn đi, mô tả như thể tế bào trong người đã chết. Vì vậy nó hầu như luôn đi với động từ sống và chết: 연애세포가 죽었다 (chết rồi), 연애세포가 살아났다 (sống lại rồi).", "de": "Eine bildliche Bezeichnung für das Gespür fürs Verliebtsein, dieses Kribbeln. Solche Zellen gibt es nicht; gemeint ist, dass der Instinkt abstumpft, wenn man lange niemanden datet — beschrieben, als seien Zellen im Körper gestorben. Deshalb steht es fast immer bei Verben des Lebens und Sterbens: 연애세포가 죽었다 (sie sind tot), 연애세포가 살아났다 (sie sind wieder erwacht)."}, "examples": [{"kor": "3년을 쉬었더니 연애세포가 다 죽었나 봐.", "eng": "Three years off and my romance cells seem to have died completely.", "ja": "3年休んだら恋愛細胞が全部死んだみたい。", "es": "Tres años sin nadie y creo que se me han muerto las células del amor.", "vi": "Nghỉ yêu ba năm chắc tế bào yêu đương chết sạch rồi.", "de": "Drei Jahre Pause — meine Liebeszellen scheinen alle abgestorben."}]}]'::jsonb, '생물학의 ''세포''를 감정에 빗대 만든 비유 표현이다. 위키백과에 독립 항목으로 올라 있을 만큼 널리 쓰이며, 실제로 존재하는 세포가 아니라는 점이 항목에 명시돼 있다. 누가 처음 이렇게 표현했는지는 확인되지 않는다.', '{"en": "A metaphor that borrows ''cell'' from biology and applies it to feelings. It is common enough to have its own Korean Wikipedia entry, which states outright that no such cell exists. Who first put it this way is unverified.", "ja": "生物学の「細胞」を感情にたとえて作った比喩表現。ウィキペディアに独立項目が立つほど広く使われ、実在する細胞ではないと項目に明記されている。誰が最初にこう表現したかは未確認。", "es": "Metáfora que toma ''célula'' de la biología y la aplica a los sentimientos. Es tan común que tiene entrada propia en la Wikipedia coreana, donde se aclara que no existe tal célula. Quién lo dijo primero no está verificado.", "vi": "Phép ẩn dụ mượn ''tế bào'' của sinh học gán cho cảm xúc. Phổ biến tới mức có mục riêng trên Wikipedia tiếng Hàn, nơi ghi rõ không hề có tế bào nào như thế. Ai nói đầu tiên thì chưa xác minh.", "de": "Eine Metapher, die ''Zelle'' aus der Biologie auf Gefühle überträgt. Sie ist so verbreitet, dass sie einen eigenen Eintrag in der koreanischen Wikipedia hat, der ausdrücklich festhält, dass es solche Zellen nicht gibt. Wer es zuerst so formulierte, ist ungeprüft."}'::jsonb, '거의 항상 ''죽다/살아나다''와 함께 쓴다. 자조 섞인 농담으로 쓰는 일이 많아, 오래 솔로인 사람이 스스로에 대해 말할 때 자주 나온다.', '{"en": "Almost always paired with 죽다 (die) or 살아나다 (revive). It''s usually self-deprecating humour, so it comes up most from people who''ve been single a long time talking about themselves.", "ja": "ほぼ必ず「死ぬ/生き返る」と一緒に使う。自嘲混じりの冗談として使うことが多く、長く独り身の人が自分について話すときによく出る。", "es": "Casi siempre con 죽다 (morir) o 살아나다 (revivir). Suele ser humor autocrítico, así que sale sobre todo de quien lleva mucho tiempo soltero hablando de sí mismo.", "vi": "Gần như luôn đi với 죽다 (chết) hoặc 살아나다 (sống lại). Thường là kiểu tự trào, nên hay xuất hiện khi người độc thân lâu năm nói về chính mình.", "de": "Fast immer mit 죽다 (sterben) oder 살아나다 (wiederaufleben). Meist selbstironisch, deshalb vor allem von Menschen, die lange Single sind und über sich selbst reden."}'::jsonb, array['모솔','금사빠','솔크'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Romance instincts"}, {"lang": "🇯🇵 JA", "text": "恋愛細胞"}, {"lang": "🇨🇳 ZH", "text": "恋爱细胞"}, {"lang": "🇻🇳 VI", "text": "Tế bào yêu đương"}, {"lang": "🇪🇸 ES", "text": "Células del amor"}, {"lang": "🇩🇪 DE", "text": "Liebeszellen"}]'::jsonb, array[]::text[]),
('409', '깨볶다', 'Kkae-Bok-Da', 'love', null, '커플이 보기 좋을 만큼 알콩달콩 잘 지내다', '{"en": "To be blissfully, visibly happy as a couple", "ja": "カップルが見ていて微笑ましいほど仲良く過ごす", "es": "Estar acaramelados de forma muy visible", "vi": "Cặp đôi ngọt ngào tới mức ai nhìn cũng thấy", "de": "Als Paar sichtbar und ungetrübt glücklich sein"}'::jsonb, '[깨복따]', '[{"type": "동사", "definition": "신혼부부나 커플이 다정하고 행복하게 지내는 모습을 이르는 말. 깨를 볶으면 고소한 냄새가 진하게 퍼지는 데서, 옆에서 봐도 분위기가 느껴질 만큼 사이가 좋다는 뜻이 됐다. ''깨가 쏟아진다''와 같은 계열이며, 주로 남이 그 커플을 두고 말할 때 쓴다.", "definition_i18n": {"en": "Said of newlyweds or a couple living in easy, visible happiness. Roasting sesame fills a room with its smell, and the phrase carries that over: the warmth is obvious to anyone nearby. It belongs to the same family as 깨가 쏟아진다, and is normally something other people say about the couple.", "ja": "新婚夫婦やカップルが仲むつまじく幸せに過ごす様子を言う語。ごまを炒ると香ばしい匂いが強く広がることから、そばで見ても雰囲気が伝わるほど仲が良いという意味になった。「깨가 쏟아진다」と同系統で、たいてい他人がそのカップルについて言うときに使う。", "es": "Se dice de recién casados o de una pareja que vive una felicidad evidente. Al tostar sésamo el olor lo inunda todo, y la expresión traslada eso: el buen ambiente se nota desde fuera. Pertenece a la misma familia que 깨가 쏟아진다 y normalmente lo dicen terceros sobre la pareja.", "vi": "Nói về đôi vợ chồng mới cưới hay cặp đôi sống hạnh phúc thấy rõ. Rang mè thì mùi thơm lan khắp nhà, và câu này mượn hình ảnh đó: ai đứng gần cũng cảm nhận được sự ấm áp. Cùng họ với 깨가 쏟아진다, và thường do người ngoài nói về cặp đôi ấy.", "de": "Gesagt über Frischvermählte oder ein Paar in sichtbar unbeschwertem Glück. Röstet man Sesam, erfüllt der Duft den ganzen Raum — genau das überträgt die Wendung: die Wärme ist für jeden in der Nähe spürbar. Sie gehört zur selben Familie wie 깨가 쏟아진다 und wird meist von anderen über das Paar gesagt."}, "examples": [{"kor": "신혼이라 그런지 아주 깨볶고 살더라.", "eng": "Newlyweds, clearly — you can feel the glow off them.", "ja": "新婚だからか、すごく仲良く暮らしてるよ。", "es": "Se nota que son recién casados: están de lo más acaramelados.", "vi": "Mới cưới có khác, nhìn ngọt ngào ghê.", "de": "Frisch verheiratet, offensichtlich — man spürt die gute Stimmung sofort."}]}]'::jsonb, '깨를 볶을 때 나는 고소한 냄새에 빗댄 관용 표현이다. ''깨가 쏟아진다''가 같은 뜻으로 더 널리 알려져 있고, ''깨볶다''는 그 계열의 동사형이다. 표준국어대사전에 ''깨볶다''는 표제어로 등재돼 있지 않다.', '{"en": "An idiom drawn from the rich smell of sesame being roasted. The better-known form of the same idea is 깨가 쏟아진다; 깨볶다 is the verb of that family. 깨볶다 is not listed as a headword in the standard Korean dictionary.", "ja": "ごまを炒るときの香ばしい匂いにたとえた慣用表現。同じ意味では「깨가 쏟아진다」の方が広く知られ、「깨볶다」はその系統の動詞形。標準国語大辞典に「깨볶다」は見出し語として未収録。", "es": "Locución tomada del olor intenso del sésamo al tostarse. La forma más conocida de la misma idea es 깨가 쏟아진다; 깨볶다 es el verbo de esa familia. 깨볶다 no figura como entrada en el diccionario estándar.", "vi": "Thành ngữ lấy từ mùi thơm đậm của mè khi rang. Dạng quen thuộc hơn của cùng ý này là 깨가 쏟아진다; 깨볶다 là dạng động từ cùng họ. 깨볶다 không có trong từ điển chuẩn với tư cách mục từ.", "de": "Eine Redewendung nach dem kräftigen Duft röstenden Sesams. Die bekanntere Form derselben Idee ist 깨가 쏟아진다; 깨볶다 ist das Verb dieser Familie. 깨볶다 steht nicht als Stichwort im Standardwörterbuch."}'::jsonb, '남의 커플을 두고 말할 때 쓰며, 부러움이 섞인 따뜻한 표현이다. 자기 커플에게 직접 쓰면 자랑처럼 들린다.', '{"en": "Said about someone else''s relationship, warmly and with a touch of envy. Applied to your own it sounds like bragging.", "ja": "他人のカップルについて言う語で、羨ましさの混じった温かい表現。自分たちに使うと自慢に聞こえる。", "es": "Se dice de la pareja de otros, con cariño y algo de envidia. Aplicado a la propia suena a presumir.", "vi": "Nói về cặp đôi của người khác, ấm áp và pha chút ganh tị. Tự nói về mình thì nghe như khoe.", "de": "Über die Beziehung anderer gesagt, warm und mit einem Hauch Neid. Auf die eigene angewandt klingt es nach Angeberei."}'::jsonb, array['럽스타그램','케미','백일'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Blissfully in love"}, {"lang": "🇯🇵 JA", "text": "仲むつまじい"}, {"lang": "🇨🇳 ZH", "text": "甜甜蜜蜜"}, {"lang": "🇻🇳 VI", "text": "Ngọt như mật"}, {"lang": "🇪🇸 ES", "text": "Estar acaramelados"}, {"lang": "🇩🇪 DE", "text": "Frisch verliebt strahlen"}]'::jsonb, array[]::text[]);

-- 썸타다는 썸(320)과 같은 말이라 표제어를 새로 세우지 않고 검색용 alias로만 넣는다.
update public.words set aliases = array['썸타다'] where id = '320' and word = '썸';

